(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-enhancing-repository-level-code-comp-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-1\">一 · 一次补全请求的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-2\">二 · 旧方案：静态检索加监督微调</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-3\">三 · 为什么开环链路非改不可</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-4\">四 · 推理栈的三段式与缓存键的脆弱性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-5\">五 · 奖励信号与推理侧的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-6\">六 · 旧方案留下的三个未解接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-7\">七 · 请求形态：长度分布决定预填与解码的预算切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-8\">八 · 并发与批大小：低延迟 SLO 下的连续批处理边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-9\">九 · 前缀缓存命中率：版本键是负载塑造方案的核心杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-10\">十 · 长尾请求：稀疏上下文与奖励延迟如何反向约束负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-11\">十一 · 测量口径清单：把负载与方案的耦合变成可核查的数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-12\">十二 · 负载形态如何反向约束策略：边界、失效条件与测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-13\">十三 · 从策略约束到 kernel 约束：KV 预算如何落到数值精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-14\">十四 · 数据类型谱系：FP16/BF16、FP8、NVFP4 在补全链路中的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-15\">十五 · 累加精度与误差传播：为什么 MMA 的累加器位宽不能省</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-16\">十六 · Blackwell 特性如何改变补全的预填/解码配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-17\">十七 · 精度选择与奖励信号的耦合：量化误差会不会污染策略学习</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-18\">十八 · 预算约束下的数值精度取舍与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-19\">十九 · 显存账本的三本账：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-20\">二十 · 分页与碎片：为什么连续分配会杀死命中率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-21\">二十一 · 压缩与复用：KV 量化、结构压缩与跨请求共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-22\">二十二 · 卸载：把冷 KV 放到哪里，代价是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-23\">二十三 · 可复算的显存预算：一个完整算例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-24\">二十四 · 带宽瓶颈定位与监控口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-25\">二十五 · 从补全请求到批的成形：连续批处理为何是默认解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-26\">二十六 · chunked prefill：把长预填切碎，换取解码步的稳定节奏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-27\">二十七 · 优先级与抢占：奖励信号如何变成调度权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-28\">二十八 · 分离式预填/解码：把两种资源需求拆到不同池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-29\">二十九 · 尾延迟怎么压：从 P99 反推调度参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-30\">三十 · 调度与策略的耦合边界：奖励回传不能直接当调度信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-31\">三十一 · 从单卡到多卡：补全请求在并行维度上的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内带宽决定了切分粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-33\">三十三 · All-Reduce 与 All-to-All：两种通信模式的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-34\">三十四 · NIXL 传输：KV 在池间的搬运与它的隐性成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-35\">三十五 · 通信何时成为瓶颈：三条可操作的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-36\">三十六 · 把并行选择接回上下文组织层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-37\">三十七 · 精度塌陷：奖励漂移与策略过拟合的现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-38\">三十八 · OOM 与 KV 预算击穿：预填峰值而非均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-39\">三十九 · 批抖动与尾延迟：命中率波动的传导链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-40\">四十 · 静默降级：缓存错配与投机不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-41\">四十一 · 回滚：以版本键为粒度的策略回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-42\">四十二 · 失效边界：从奖励语义漂移到缓存版本错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-43\">四十三 · 口径的第一性问题：这篇论文没有可比的数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-44\">四十四 · 硬件档位与 batch/并发的耦合：为什么 batch 不能单独报</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-45\">四十五 · 指标定义：TTFT、TPOT、吞吐、显存、功耗各自的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-46\">四十六 · 奖励口径与离线指标的错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-47\">四十七 · 哪些提升不可比：四类典型误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-48\">四十八 · 复现口径的最小清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-49\">四十九 · 口径拆解：奖励信号与 KV 预算的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-50\">五十 · 迁移到非代码领域：奖励语义先塌，再谈上下文</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-51\">五十一 · 迁移到其他代码模型：改的是缓存键与草稿一致性，不是策略头</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-52\">五十二 · 规模上限：KV 预算与 SLO 的联合约束决定天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-53\">五十三 · 哪里不适用：三类场景应当直接放弃这套策略层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-54\">五十四 · 迁移检查清单：把改动落到可核验的接口上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-enhancing-repository-level-code-comp-2026-sec-55\">五十五 · 迁移边界：策略层可移植，奖励与缓存契约不可移植</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入：编辑器携带当前文件、光标位置与仓库快照，形成补全请求并附带版…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">上下文组织：按跨文件依赖与编辑历史挑选候选片段，决定进入提示的仓库上下…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前缀缓存：以文件路径与版本为键复用已编码前缀，未命中部分重新预填并写入…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码生成：在低延迟约束下自回归生成补全候选，必要时用草稿模型加速。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">奖励回传：补全被采纳或通过校验后形成序列级奖励，更新上下文选择与生成策…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-1\">一 · 一次补全请求的真实代价</h3>\n<p>设想一个中等规模团队的在线 IDE 服务：几十名工程师同时在各自分支上编辑，编辑器插件在每次停顿后向推理集群发一个补全请求。请求体不只是当前文件和光标位置，还附带仓库快照标识与一组候选跨文件片段——被编辑函数的调用方、接口定义、相邻测试。服务端要在用户下一次敲键前把候选补全送回去，这就是低延迟补全 SLO 的物理来源：它不是某个配置项，而是人的打字节奏。</p>\n<p>这条路径上的开销分成三段。第一段是预填：候选跨文件片段与当前文件前缀一起送进模型，前向计算出 KV。第二段是解码：自回归逐 token 生成补全候选，直到遇到自然终止或长度上限。第三段是回传与采纳判定。三段里最贵的是第一段，因为仓库级上下文的 token 数远超补全本身——补全可能只有十几个 token，而支撑它的跨文件证据可能是数千 token。用公式表达这条约束：</p>\n<div class=\"formula\">$$t_{\\text{req}} = t_{\\text{prefill}}(1-h) + t_{\\text{decode}}(n_{\\text{out}}) + t_{\\text{net}} \\le t_{\\text{SLO}}$$</div>\n<p>其中 $h$ 是前缀缓存命中率。这个式子的工程含义很直接：$h$ 每下降一点，预填开销就线性回灌到请求延迟上。而仓库编辑流的特性是文件版本高频变动——用户每敲一次保存，当前文件版本就变，以文件路径与版本为键的前缀缓存立刻错配，命中段作废，重新预填。真实在线服务里，缓存命中率的抖动往往比模型本身的算力波动更致命。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-2\">二 · 旧方案：静态检索加监督微调</h3>\n<p>这篇论文之前，仓库级补全的主流推理栈是“静态检索 + 监督微调”的两段式。检索侧用 BM25、嵌入相似度或 AST 结构匹配，从仓库里捞出一批跨文件片段，按固定规则排序、按固定 token 预算截断，拼进提示；生成侧是一个在代码语料上做过监督微调的模型，只对齐下一个 token 的似然。整条链路是开环的：检索选什么，模型就吃什么，没有任何环节根据“补全最终有没有被用上”来调整上下文的选择。</p>\n<p>这套做法在离线基准上能跑出好看的指标，因为基准的仓库快照是冻结的、上下文是预先切好的。但真实编辑流里，跨文件证据既稀疏又噪声大：一个函数真正的语义依赖可能藏在三层调用之外，而检索器因为词面不匹配把它漏掉；反过来，检索器又会因为命名相似塞进一堆无关片段，把 KV 预算吃掉。监督信号只对齐下一个 token，模型学不会“这段跨文件上下文对本次补全有没有用”，它只学会“在给定上下文下续写最可能的 token”。</p>\n<p>代价体现在三个维度上。显存侧：为了不漏掉证据，旧方案倾向把上下文预算开大，KV 全量驻留，单请求 KV 占用随仓库上下文线性膨胀，并发一上来就撞显存墙。延迟侧：预填的 token 数被固定预算锁死，缓存命中率低时预填开销无法摊薄，尾延迟直接突破 SLO。吞吐侧：长上下文请求把 batch 撑大，小批低时延的补全场景被迫与大 batch 争抢 SM，连续批处理的调度空间被压缩。三者互相咬合，任何单点优化都会被另外两点拉回去。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-3\">三 · 为什么开环链路非改不可</h3>\n<p>问题的根子在于：上下文选择与生成质量是两个本该联合优化的决策，旧方案把它们拆成了两个互不通信的阶段。检索器不知道生成器需要什么，生成器不知道检索器给了什么代价。这在推理系统里表现为一个具体的失败模式——KV 预算紧张时，系统仍然全量保留检索出的跨文件上下文，预填开销抵消掉缓存收益，请求延迟突破 SLO，而补全质量并没有因为多喂了上下文而提升，因为多喂的那部分本来就是噪声。</p>\n<p>论文的切入点是把这个开环改成闭环：以真实仓库编辑流为环境，用强化学习对补全策略做序列级优化，奖励来自补全是否被采纳或通过校验。目标函数写成带约束的形式：</p>\n<div class=\"formula\">$$\\max_{\\pi}\\ \\mathbb{E}_{x\\sim\\mathcal{D},\\ y\\sim\\pi(\\cdot\\mid x)}\\left[\\,r(x,y)\\,\\right]\\quad\\text{s.t.}\\quad |\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}},\\ \\ t_{\\mathrm{decode}}\\le t_{\\mathrm{SLO}}$$</div>\n<p>这个式子的工程价值不在于 RL 本身，而在于它把“哪些仓库上下文值得进入前缀缓存与草稿模型”变成了一个可学习的决策，而不是一条写死的截断规则。策略 $\\pi$ 同时在选上下文和生成补全，奖励把两者绑在一起：选了高价值证据、生成了被采纳的补全，才拿到正奖励；选了噪声、生成了没人用的补全，奖励为零。约束项则把 KV 预算和解码时延写进可行域，避免策略为了刷奖励而无节制地扩上下文。</p>\n<p>一个具体例子：用户正在改一个支付回调函数，光标停在参数校验处。旧方案按词面相似度检索，可能捞进同名的日志工具函数，占掉大半 KV 预算；闭环策略在若干次采纳反馈后学到，调用链上游的订单状态枚举才是高价值证据，日志工具函数的片段几乎从不带来被采纳的补全，于是把它挤出预算。省下的 KV 预算让前缀缓存能多驻留几个高频文件版本，命中率上升，预填开销下降，尾延迟回到 SLO 之内。这是策略层信号反过来改善推理侧缓存经济性的路径。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-4\">四 · 推理栈的三段式与缓存键的脆弱性</h3>\n<p>从任务定位看，推理侧由仓库上下文组织层、前缀缓存与 KV 管理、补全解码器三部分构成。上下文组织层决定跨文件片段进入提示的顺序与截断位置——这个顺序不是无关紧要的细节，它决定了前缀缓存能复用到哪一段。前缀缓存按文件路径与版本做键复用，命中部分直接复用 KV，未命中部分重新预填。解码器在低延迟约束下输出补全，若启用投机解码则由草稿模型先出候选再验证。</p>\n<p>缓存键的脆弱性是这套结构里最容易被低估的工程风险。以文件路径与版本为键，意味着当前文件一旦被编辑，它的 KV 就整体失效；而跨文件片段的版本变动同样会让缓存错配。错配不只是“没命中”这么简单——如果版本标识设计不当，系统可能复用了一个语义上已经过时的 KV，污染补全结果。这在真实编辑流里是高频事件，因为用户保存的频率远高于模型推理的节奏。工程上的应对是把缓存键做成内容寻址而非路径寻址，让未变动的跨文件片段在文件重命名、移动后仍能命中，同时用版本号严格隔离已变动的前缀。</p>\n<p>代价核算：前缀缓存命中率每提升一档，预填 token 数就同比下降，直接换算成尾延迟的收敛；但缓存本身要吃显存，驻留的文件版本越多，可用于并发的 KV 预算越少。这是一个显存与延迟的对冲，而 RL 策略给出的上下文价值排序，恰好可以作为缓存淘汰的优先级依据——高价值证据对应的文件版本优先驻留，低价值片段对应的版本优先驱逐。这把策略层的输出变成了 KV 管理的输入，是这篇论文在推理机制上最可复用的接口。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-5\">五 · 奖励信号与推理侧的耦合代价</h3>\n<p>奖励来自补全是否被采纳或通过校验，这意味着奖励是稀疏且延迟的：用户可能几秒后才按下 Tab，也可能根本不采纳。对推理系统而言，这带来两个耦合代价。其一是反馈回路的时延：策略更新依赖采纳信号回流，而在线服务的请求速率远高于策略收敛速度，系统必须在策略滞后的情况下继续服务，缓存与预算分配只能按上一版策略执行。其二是奖励噪声：用户不采纳不等于补全错误，可能只是他正在写别的东西；校验通过也不等于补全最优。噪声进入策略，会让上下文选择的排序在相邻请求间抖动，进而让缓存驻留决策抖动，命中率随之抖动。</p>\n<p>伪代码层面的请求路径可以写成：</p>\n<div class=\"formula\">$$\\text{req}\\rightarrow \\text{ctx}(f,c,\\text{snap})\\rightarrow \\text{rank}\\&amp;\\text{trunc}(B_{\\text{kv}})\\rightarrow \\text{cache\\_lookup}(\\text{path},\\text{ver})\\rightarrow \\text{prefill}(1-h)\\rightarrow \\text{decode}\\rightarrow \\text{reward}$$</div>\n<p>这条路径上每一环都有失败模式。上下文组织层若按依赖关系与编辑历史排序后截断到 KV 预算内，截断点落在哪个片段边界上，直接决定前缀缓存能复用到哪一段；缓存查找若版本错配，触发重新预填，解码时延可能超出约束；解码器若启用投机解码，草稿模型与仓库上下文的一致性未在材料中给出验证，草稿被拒率高时加速收益被验证开销吃掉。论文未给出硬件档位与并行拓扑，因此部署侧只能按机制推断：在 Blackwell 上，这套结构对前缀缓存与 KV 预算的依赖是刚性的，NVFP4/FP8 量化能压低 KV 与权重显存，但补全质量是否守住需要自行验证。</p>\n<p>把奖励信号与推理侧约束关联，是这篇论文给出的策略层思路：不是让 RL 去优化一个离线指标，而是让它在 KV 预算与解码时延的可行域内，学会哪些跨文件证据值得进入前缀缓存、哪些值得喂给草稿模型。这个思路的可检验性在于，它把上下文选择从一条静态规则变成了一个可以被缓存命中率、KV 占用、补全采纳率三项监控共同观测的在线决策。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-6\">六 · 旧方案留下的三个未解接口</h3>\n<p>回到问题现场，旧方案留下的不是“效果不够好”这种笼统判断，而是三个具体的未解接口。第一，上下文预算的分配是静态的：固定 token 上限、固定排序规则，无法随仓库编辑流的动态性调整，导致 KV 预算在噪声片段上浪费、在高价值证据上不足。第二，缓存复用与语义正确性之间没有隔离机制：路径与版本做键，版本错配即失效，缺少内容寻址与语义过时检测，复用错误 KV 的风险直接落在补全结果上。第三，生成策略与上下文选择之间没有反馈通道：监督微调只对齐下一个 token，模型无法表达“这段上下文对本次补全无用”，系统也就无法据此收缩预算。</p>\n<p>这三个接口正是这篇论文用序列级 RL 去触碰的地方：把上下文选择与生成质量联合优化，让奖励来自补全可用性而非 token 似然，把 KV 预算与解码时延写成约束。工程判断上，它的价值不在于给出了一套可直接部署的推理栈——材料未给出数据集规模、基线名称与数字结果，也未给出硬件档位与并行拓扑——而在于它指出了策略层与推理层之间的接口应该长什么样：上下文组织层的输出要能被缓存淘汰策略消费，缓存命中率要能反过来约束策略的预算分配，奖励信号要能在稀疏与延迟的条件下保持排序稳定。这三条接口在 Blackwell 部署中对应的是前缀缓存键设计、KV 预算分配与投机解码草稿模型的一致性验证，任何一条没打通，长上下文复用的收益都会被预填开销抵消。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-7\">七 · 请求形态：长度分布决定预填与解码的预算切分</h3>\n<p>仓库级补全请求不是一个固定形状的张量，而是由当前文件、光标位置、仓库快照三者拼出的变长输入。其长度分布呈明显双峰：绝大多数请求只涉及当前文件与少量同目录上下文，落在短输入一侧；少数跨模块重构或接口变更请求会把多个文件的依赖片段拉进提示，形成长尾。这个分布直接决定推理侧的资源切分——短请求的瓶颈在解码步数与调度往返，长请求的瓶颈在预填算力与前缀缓存命中率。用可核查的口径描述它，需要同时记录 token 计数的分位数（p50/p90/p99）与“跨文件片段占比”，后者定义为进入提示的非当前文件 token 数除以总输入 token 数；只报平均长度会掩盖长尾对 KV 预算的挤压。</p>\n<p>设单请求输入 token 数为 <span class=\"inline-math\">L</span>，其中可被前缀缓存复用的部分为 <span class=\"inline-math\">L_hit</span>，则预填代价近似正比于 <span class=\"inline-math\">L - L_hit</span>，而 KV 驻留代价正比于 <span class=\"inline-math\">L</span> 全量。论文的约束形式把这两件事绑在一起：</p>\n<div class=\"formula\">$$\\max_{\\pi}\\ \\mathbb{E}_{x\\sim\\mathcal{D},\\ y\\sim\\pi(\\cdot\\mid x)}\\left[\\,r(x,y)\\,\\right]\\quad\\text{s.t.}\\quad |\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}},\\ \\ t_{\\mathrm{decode}}\\le t_{\\mathrm{SLO}}$$</div>\n<p>工程含义是：上下文组织层的截断决策不是质量与成本的二选一，而是在 <span class=\"inline-math\">\\(B_{\\mathrm{kv}}\\)</span> 内最大化“可复用且高价值”的片段占比。一个具体例子：某请求光标位于一个被三个模块调用的工具函数签名处，候选片段包括该函数的定义文件、两个调用点文件与一份近期编辑历史。若把两个调用点文件全部纳入，输入长度翻倍但其中大部分 token 与当前补全无关，预填开销上升而命中率不升；若只保留定义文件的签名区与最近一次编辑 diff，KV 占用下降且该文件版本在后续请求中更可能被再次命中。测量口径上，应把“每次请求的 KV 峰值”与“该请求触发的重预填 token 数”作为一对指标上报，二者之比即缓存摊薄效率。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-8\">八 · 并发与批大小：低延迟 SLO 下的连续批处理边界</h3>\n<p>代码补全的并发形态与聊天推理不同：它由大量编辑器实例的零散击键触发，请求到达率高但单请求输出极短（通常几十个 token 即一个补全片段），且用户对首 token 延迟极度敏感。这使连续批处理（continuous batching）的收益结构发生变化——批内 token 生成量小，调度器在“攒批以提升吞吐”与“立即发射以压低延迟”之间的权衡窗口很窄。可核查的口径包括：到达率（请求/秒/活跃编辑器）、批大小分布（实际执行的批内请求数直方图）、以及排队时延与解码时延的分解。只报端到端 p99 而不拆分排队与计算，无法判断瓶颈在调度还是在算力。</p>\n<p>伪代码层面的调度判断可写成：当队列中最早请求的已等待时间逼近 SLO 余量减去其预估解码时间时，必须强制发射当前批，即使批未填满。</p>\n<ul>\n<li>预估解码时间 ≈ 输出 token 上限 × 单步解码时延，后者随批大小与 KV 长度增长；</li>\n<li>若某请求的 <span class=\"inline-math\">L - L_hit</span> 很大，其预填会占用整个批的算力窗口，调度器应将其与短请求隔离，避免长预填拖累同批短请求的首 token 延迟；</li>\n<li>批内 KV 总占用是硬约束：批大小不能只看请求数，要看 <span class=\"inline-math\">\\(\\sum_i |\\mathrm{KV}(x_i)|\\)</span> 是否越过显存水位。</li>\n</ul>\n<p>具体例子：一个 8 卡节点上同时有 200 个活跃编辑器会话，击键触发率在编辑高峰集中。若按请求数攒到 32 再发射，批内混合了三个需要跨文件重预填的长请求，短请求的首 token 延迟被长预填拉长；若按 KV 占用而非请求数分批，把长预填请求单独成批并让其预填与短批的解码在时间上错开，短请求的延迟分布明显收窄。代价是长请求的完成时间变长，这需要在 SLO 定义中区分“首 token 延迟”与“补全完成延迟”两个口径，否则调度策略会被单一指标误导。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-9\">九 · 前缀缓存命中率：版本键是负载塑造方案的核心杠杆</h3>\n<p>论文的推理侧以文件路径与版本为键复用 KV，这一设计把负载形态与方案能力直接耦合。命中率不是被动统计量，而是被上下文组织层的截断与排序策略主动塑造的：截断若按依赖关系稳定排序，同一文件版本在不同请求中进入提示的前缀位置一致，缓存可复用；截断若随编辑历史频繁变动顺序，同一文件的 KV 块无法对齐，命中率塌陷。可核查口径应区分三级：块级命中率（复用 KV 块数/总块数）、请求级全命中率（<span class=\"inline-math\">L_hit = L</span> 的请求占比）、以及版本错配率（因文件版本变化导致键失效的请求占比）。</p>\n<p>版本错配是这套机制的主要失败模式：编辑器携带的仓库快照版本与缓存中驻留的版本不一致时，复用错误 KV 不仅无益，还会污染补全结果。工程上需要把“版本校验”放在缓存查找之前，并在校验失败时降级为重新预填而非强行复用。代价体现在延迟上：一次全量重预填的长请求可能吃掉数十毫秒级的算力窗口，在低延迟 SLO 下足以让该请求超时。因此监控必须把“重预填触发次数”与“重预填 token 总量”作为一等指标，与命中率并列上报。</p>\n<p>具体例子：某仓库在一次批量重命名后，多个文件的路径键未变但内容版本全变。若缓存仅按路径匹配而不校验版本，后续请求会命中旧 KV，补全引用旧符号名；若按路径加版本校验，则短时间内命中率骤降、重预填集中爆发，形成延迟尖峰。可核查的测量是在重命名事件窗口内按分钟粒度记录命中率与 p99 解码时延的联合曲线，用以判断缓存失效的恢复速度是否满足 SLO。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-10\">十 · 长尾请求：稀疏上下文与奖励延迟如何反向约束负载</h3>\n<p>负载的长尾不只是长度长尾，还有价值长尾：多数请求的跨文件证据稀疏，少数请求才真正需要跨模块上下文。论文用强化学习优化上下文选择，其策略输出会反过来改变负载形态——策略若学会对某类请求少取上下文，这类请求的输入长度分布会向短端收缩，预填压力下降；策略若对采纳率高的场景多取证据，长请求占比上升，KV 预算被挤压。这是一个闭环：负载塑造方案，方案通过策略改变后续负载的分布。可核查的口径是“策略更新前后同一仓库同一编辑会话的输入长度分位数变化”与“跨文件片段占比变化”，二者共同刻画策略对负载的反作用。</p>\n<p>奖励稀疏且依赖用户采纳，使这个闭环带滞后：一次补全被采纳的信号可能在数秒后才回传，而在此期间同一会话已产生多个请求。若策略更新过快，会把延迟反馈误归因到错误的上下文选择上。工程判断是给奖励回传加上会话与版本标识，使策略更新只作用于可归因的请求族，而非全局漂移。代价是策略收敛变慢，但避免了在真实编辑流中因噪声导致的上下文选择震荡——震荡本身会破坏前缀缓存的顺序稳定性，间接拉低命中率。</p>\n<p>具体例子：某开发者在重构一个接口，连续多次请求都涉及同一组跨文件依赖，采纳信号集中且正向；策略会倾向对该文件族多取上下文。而同一仓库另一角落的偶发请求证据稀疏、采纳信号零散，策略对其趋于保守。若不区分请求族，全局策略会在两者间折中，导致高价值场景上下文不足、低价值场景上下文冗余，两头都付出代价。测量上应以请求族为单位统计采纳率与平均输入长度，观察策略是否把预算从低采纳族向高采纳族迁移。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-11\">十一 · 测量口径清单：把负载与方案的耦合变成可核查的数</h3>\n<p>上述讨论要落地，需要一套不依赖论文未给出数字的口径体系。以下指标均可在推理服务侧采集，且不预设硬件档位与量化方案：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>口径</th><th>定义</th><th>回答的问题</th></tr>\n</thead>\n<tbody>\n<tr><td>输入长度分位数</td><td>p50/p90/p99 的输入 token 数，按请求族分组</td><td>长尾是否挤压 KV 预算</td></tr>\n<tr><td>跨文件片段占比</td><td>非当前文件 token / 总输入 token</td><td>上下文组织层是否过度取证</td></tr>\n<tr><td>块级命中率</td><td>复用 KV 块数 / 总块数</td><td>截断排序是否稳定</td></tr>\n<tr><td>版本错配率</td><td>键失效请求 / 总请求</td><td>缓存正确性风险</td></tr>\n<tr><td>重预填 token 总量</td><td>未命中部分重新预填的 token 数</td><td>预填开销是否被摊薄</td></tr>\n<tr><td>排队/解码时延分解</td><td>端到端 p99 拆为排队与计算两段</td><td>瓶颈在调度还是算力</td></tr>\n<tr><td>批大小直方图</td><td>实际执行批内请求数与 KV 总占用</td><td>连续批处理是否越过显存水位</td></tr>\n<tr><td>采纳率（按请求族）</td><td>被采纳或校验通过的补全 / 总补全</td><td>策略是否把预算迁移到高价值族</td></tr>\n</tbody>\n</table>\n<p>这套口径的关键在于成对上报：命中率必须与重预填 token 总量同报，否则高命中率可能掩盖少数全量重预填造成的延迟尖峰；批大小必须与批内 KV 总占用同报，否则请求数达标但显存越界；采纳率必须按请求族分组，否则全局平均会掩盖策略在长尾上的失效。论文未给出具体数据集规模、基线名称与数字结果，因此这些口径的作用不是复现其数值，而是把“负载如何塑造方案、方案如何反向限制负载”这一机制变成可观测、可回归的工程对象。</p>\n<p>最后一个具体判断落在缓存键的设计上：若版本校验放在查找之后，错配 KV 会进入解码并污染补全，其代价是一次错误补全引发的用户返工，远高于一次重预填的延迟；若放在查找之前，代价是重命名等批量变更窗口内的命中率骤降与延迟尖峰。两种代价都可测量，选择取决于该仓库编辑流的变更频率与 SLO 对尖峰的容忍度——这正是负载形态与方案设计互为约束的落点。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-12\">十二 · 负载形态如何反向约束策略：边界、失效条件与测量口径</h3>\n<p>该方案的边界不在算法本身，而在请求形态与 KV 预算的耦合处。上下文组织层必须在 <span class=\"formula\">$$|\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}},\\ t_{\\mathrm{decode}}\\le t_{\\mathrm{SLO}}$$</span> 两个约束下截断跨文件片段，而真实编辑流的输入长度分布是长尾的：多数请求只涉及当前文件的小范围编辑，少数请求跨越多个依赖文件、上下文规模陡增。长尾请求正是前缀缓存命中率的分母杀手——它们未命中比例高、预填开销大，却占据 SLO 尾延迟的主要份额。若按均值批大小与均值上下文长度做容量规划，尾部的预填排队会把解码时延推过 SLO；反之若按最长请求配置，KV 显存被长尾独占，短请求的并发被压低。因此测量口径必须分离：按请求记录输入 token 数的分位数（而非均值）、前缀缓存命中率按文件路径与版本键统计、预填耗时与解码耗时分开计时、批大小按到达时刻快照记录，并单列“版本错配导致的缓存失效次数”。</p>\n<p>方案反过来限制负载的机制体现在准入与截断策略上。上下文组织层按依赖关系与编辑历史排序并截断到 KV 预算内，这一截断本身改变了请求的有效长度分布：被截掉的跨文件证据不会进入前缀缓存，后续请求即使引用同一文件也无法命中，形成“截断—低命中—高预填”的正反馈。失效条件很具体：当编辑流中文件版本更迭频繁（保存、切换分支、批量重构），以路径与版本为键的缓存大面积错配，复用错误 KV 不仅污染补全结果，还会触发重新预填，把本已紧张的解码时延进一步推高。此时强化学习策略学到的“高价值跨文件证据”偏好会与缓存现实脱节——策略倾向选更多跨文件片段，而缓存命中率下降使这些片段的预填代价无法摊薄，SLO 被突破。工程判断是：把缓存命中率作为策略奖励的辅助约束项，而非仅优化采纳信号。</p>\n<p>奖励侧的负载塑造同样有代价。奖励依赖用户采纳或校验通过，信号稀疏且反馈延迟，策略更新滞后于编辑流的版本漂移；在低延迟补全场景下，用户对慢补全的采纳率下降，会与解码时延形成混杂，使策略误把“时延导致的低采纳”学成“上下文无价值”。可核查的口径是把采纳率按解码时延分桶统计，并记录每次请求的上下文截断比例与缓存命中状态，三者联合才能区分策略质量与系统瓶颈。投机解码可摊薄解码时延，但草稿模型与仓库上下文的一致性未在材料中验证，若草稿基于过期文件版本生成候选，验证阶段会大量拒绝，反而增加时延——这要求草稿模型与前缀缓存共用同一版本键。</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>失效信号</th></tr></thead><tbody><tr><td>输入长度</td><td>按请求分位数，分文件内/跨文件</td><td>长尾占比上升而命中率下降</td></tr><tr><td>前缀缓存命中率</td><td>按路径+版本键，单列错配次数</td><td>错配触发重预填，尾延迟抬升</td></tr><tr><td>时延</td><td>预填与解码分开计时，按批大小快照</td><td>预填排队挤占解码 SLO</td></tr><tr><td>采纳率</td><td>按解码时延与截断比例分桶</td><td>时延混杂导致策略误判</td></tr></tbody></table>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-13\">十三 · 从策略约束到 kernel 约束：KV 预算如何落到数值精度</h3>\n<p>论文的优化问题把上下文预算写成 \\(|\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}}\\)，这一约束在推理栈里并不是抽象符号，它最终由每个 token 的 KV 字节数乘以层数、头数与序列长度决定。若把单 token KV 占用记为 \\(s_{\\mathrm{kv}}\\)（字节/token/层），则总占用近似为 \\(L\\cdot H\\cdot d_h\\cdot b\\cdot N_{\\mathrm{tok}}\\)，其中 \\(b\\) 是每元素位宽。位宽从 BF16 降到 FP8、再降到 NVFP4，\\(b\\) 依次收缩，预算内可容纳的跨文件片段数量随之上升——这正是论文中“哪些仓库上下文值得进入前缀缓存”的策略决策在硬件侧的物理边界。反过来，精度越低，KV 复用的收益越大，但补全片段的数值误差也越难被奖励信号掩盖：奖励稀疏时，量化引入的退化不会被策略及时纠正。因此本部分的角度不是“量化能省多少显存”，而是“在 Blackwell 上，精度选择如何改变上下文组织层的可行域”。</p>\n<p>具体机制上，Blackwell 的第五代 Tensor Core 通过 tcgen05 指令族把矩阵乘的累加器放进 TMEM（Tensor Memory），使 MMA 的累加不再占用寄存器堆的常规路径。对推理而言，这意味着长上下文预填阶段的大矩阵乘可以在更低的寄存器压力下维持高占用率，从而让“未命中部分重新预填”这一代价项在 SLO 内更可控。代价是 TMEM 容量有限，一个 CTA 能驻留的累加器 tile 数量受限，预填时若序列过长需要分块，分块边界与 KV 写入的粒度必须对齐，否则前缀缓存的键匹配会退化为按块失效。举例：一个仓库请求携带当前文件与三个跨文件依赖片段，上下文组织层截断到预算内后，预填被切成若干 tile；若某依赖文件版本在两次请求间发生编辑，按文件路径与版本为键的缓存只失效该文件对应的块，其余块继续复用，预填开销被摊薄。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-14\">十四 · 数据类型谱系：FP16/BF16、FP8、NVFP4 在补全链路中的位置</h3>\n<p>推理链路上有三处数值决策点：权重、激活与 KV。FP16 与 BF16 位宽相同但指数位不同，BF16 的动态范围更适合长上下文里跨文件片段的激活分布波动；FP8 分 E4M3 与 E5M2 两种格式，前者精度高、后者范围大，通常权重与激活用 E4M3、梯度类场景用 E5M2，但推理侧只需前者。NVFP4 是 Blackwell 引入的 4 位浮点块量化格式，配合块级缩放因子使用，把每 16 个元素共享一个缩放，从而在极低位宽下保留局部动态范围。对仓库级补全而言，KV 用 NVFP4 存储的直接后果是 \\(s_{\\mathrm{kv}}\\) 降到 BF16 的四分之一左右，预算 \\(B_{\\mathrm{kv}}\\) 内可保留的跨文件证据数量成倍增加，这与论文“在有限上下文预算内选择跨文件证据”的策略目标同向。</p>\n<p>但精度下降不是均匀的。补全任务对标识符、括号、缩进等结构 token 的精确性敏感，而这些 token 的表示往往落在激活的尾部，块量化的截断误差会优先伤及它们。一个可操作的判断是：权重与预填阶段的大矩阵乘可激进用 NVFP4，解码阶段的 KV 读取与注意力打分保留 FP8，输出前的 logits 计算回到 BF16。代价体现在带宽上：KV 以 NVFP4 驻留时，解码每步读取的字节数下降，HBM 带宽压力缓解，但反量化到 FP8/BF16 参与 MMA 需要额外的转换指令，若转换与 tcgen05 的流水不能重叠，解码时延反而上升。这就是精度收益与 kernel 效率之间的真实权衡，而非单调的“越低越好”。</p>\n<div class=\"formula\">$$\\hat{x}=\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),\\quad s=\\frac{\\max(|x_{\\mathrm{blk}}|)}{2^{b-1}-1},\\quad \\varepsilon\\le \\frac{s}{2}$$</div>\n<p>逐项解释：\\(\\hat{x}\\) 是量化后的整数值，\\(s\\) 是块内缩放因子，由块内最大绝对值与位宽 \\(b\\) 决定；\\(b=4\\) 时可用整数范围远小于 FP8，因此块越小、\\(s\\) 越贴合局部分布，误差上界 \\(\\varepsilon\\) 越小。对 KV 而言块大小决定了一个缩放因子覆盖多少 token，块过大则跨文件片段拼接处的分布跳变被同一缩放压平，误差在边界 token 上放大——这正好对应论文中上下文组织层按依赖关系排序、截断的拼接点。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-15\">十五 · 累加精度与误差传播：为什么 MMA 的累加器位宽不能省</h3>\n<p>低精度输入不等于低精度累加。tcgen05 的 MMA 在 TMEM 中以较高位宽累加，输入 FP8 或 NVFP4、累加 FP32，这是保证长上下文注意力数值稳定的前提。若累加也降到 FP16，点积长度达到数千 token 时舍入误差累积会显著改变注意力权重分布，表现为补全候选的排序漂移。误差传播可以写成：单次点积的相对误差随累加项数 \\(n\\) 近似按 \\(\\sqrt{n}\\cdot u\\) 增长，\\(u\\) 是单位舍入误差；FP16 的 \\(u\\) 约为 \\(2^{-11}\\)，FP32 约为 \\(2^{-24}\\)，两者在 \\(n\\) 较大时的差距直接决定跨文件证据的相对权重是否可信。</p>\n<div class=\"formula\">$$\\frac{|\\hat{y}-y|}{|y|}\\lesssim \\sqrt{n}\\,u_{\\mathrm{acc}}+\\frac{u_{\\mathrm{in}}\\,\\|x\\|\\,\\|w\\|}{|y|}$$</div>\n<p>第一项是累加舍入的随机游走上界，第二项是输入量化误差经点积放大的部分。对仓库补全的含义是：当上下文组织层把多个跨文件片段拼进同一注意力窗口，\\(n\\) 变大，第一项主导；此时保住 FP32 累加比保住输入精度更划算。工程代价是 TMEM 中 FP32 累加器占用更多容量，单 CTA 可并行的 tile 数下降，预填吞吐受影响。一个具体取舍：预填阶段用 FP8 输入加 FP32 累加换取吞吐，解码阶段对 KV 的反量化保持 FP8 精度并维持 FP32 累加，避免在低延迟路径上引入额外的误差校正逻辑。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-16\">十六 · Blackwell 特性如何改变补全的预填/解码配比</h3>\n<p>2-SM MMA 是 Blackwell 上另一项影响推理形态的机制：两个 SM 协同执行一个更大的 MMA tile，等效于把矩阵乘的并行度在 SM 对之间重新分配。对仓库级补全，预填阶段是长序列的大矩阵乘，2-SM MMA 能提高单次指令的计算密度，减少指令发射开销；解码阶段则是小 batch、窄矩阵乘，2-SM 协作的收益被同步开销抵消，通常退回单 SM。这意味着前缀缓存未命中触发的重新预填在 Blackwell 上更快，而解码步的时延改善有限——恰好匹配论文的约束结构：预填开销需被缓存命中摊薄，解码时延受 SLO 硬约束。</p>\n<p>代价落在功耗与占用上：2-SM MMA 与 tcgen05 的高占用率使 SM 对的功耗密度上升，在 GB200 NVL72 这类高密度机架里，持续预填会推高单机架功率，容量规划需把预填突发与解码稳态分开核算。一个具体例子：编辑流中出现批量保存事件，多个文件的版本同时变更，前缀缓存大面积失效，预填突发在数秒内集中发生；若按解码稳态的功耗预算配置，预填突发会触发降频，反而拉长补全时延。工程判断是把预填的并发度与缓存失效速率联动限流，而不是让 2-SM MMA 满负荷追赶。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>数值配置</th><th>Blackwell 机制</th><th>主要代价</th></tr></thead><tbody><tr><td>预填（未命中）</td><td>权重 NVFP4/FP8，累加 FP32</td><td>tcgen05 + 2-SM MMA</td><td>TMEM 容量、功耗密度</td></tr><tr><td>解码</td><td>KV FP8，累加 FP32</td><td>单 SM MMA、TMEM 驻留</td><td>反量化转换、HBM 带宽</td></tr><tr><td>缓存复用</td><td>KV NVFP4 驻留</td><td>按版本键匹配</td><td>版本错配导致整块失效</td></tr></tbody></table>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-17\">十七 · 精度选择与奖励信号的耦合：量化误差会不会污染策略学习</h3>\n<p>论文的奖励来自补全是否被采纳或通过校验，这是一个序列级、稀疏且带延迟的信号。量化误差对奖励的影响不是随机的：它系统性地偏向高频 token 与常见代码模式，使策略在低精度部署下更倾向生成“安全但平庸”的补全，跨文件证据的独特信息被数值噪声淹没。换句话说，精度下降会改变策略的探索分布，而奖励稀疏使这种偏移难以被纠正。工程上的对策是把量化配置作为策略评估的一个维度：同一上下文组织策略在 BF16 与 NVFP4 下分别测量采纳率，若差异超出阈值，则说明该策略对数值误差敏感，应回退精度或调整块大小。</p>\n<p>这与前缀缓存的版本键直接相关。缓存以文件路径与版本为键，若同一文件在不同精度配置下产生不同 KV，键必须包含精度标识，否则复用错误精度的 KV 会污染补全结果——这是论文失败模式中“缓存版本错配”的数值版本。具体机制是：缓存条目记录文件路径、版本号与量化格式三元组，命中判定要求三者一致；编辑流中版本变更触发失效，精度配置变更触发整池重建。代价是缓存元数据膨胀与重建时的预填突发，需与第四节的限流联动。</p>\n<p>最后落到一个可执行的判断：在 Blackwell 上部署该论文的补全策略时，先固定累加精度为 FP32、KV 驻留用 FP8，把 NVFP4 只用于权重与预填矩阵乘，观察前缀缓存命中率与采纳率的联合变化；若命中率提升而采纳率不降，再逐步把 KV 降到 NVFP4 并缩小块尺寸。这个顺序把数值误差隔离在非关键路径上，使策略层学到的上下文选择信号不被量化噪声改写。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-18\">十八 · 预算约束下的数值精度取舍与失效边界</h3>\n<p>该方案的强化学习策略只决定“哪些跨文件片段进入提示”，而进入提示后的张量以何种精度驻留、以何种精度累加，直接决定 KV 预算 B<sub>kv</sub> 与解码时延 t<sub>SLO</sub> 能否同时满足。约束式中的 |KV(x)|≤B<sub>kv</sub> 在 Blackwell 上并非固定字节数：同一段仓库上下文以 BF16 驻留与以 FP8 驻留，占用相差近一倍，可容纳的跨文件证据数量随之变化。因此上下文组织层的截断决策必须与量化档位联合求解，而非先截断再量化。tcgen05 的 TMEM 累加器与 2-SM MMA 让大块预填的矩阵乘在 SM 对之间协同执行，但 FP8 路径的累加仍在 FP32 域完成，误差主要来自输入量化的舍入而非累加溢出；NVFP4 的块级缩放进一步压缩权重与激活，代价是补全这类长尾 token 分布对量化噪声更敏感。</p>\n<div class=\"formula\">$$\\Delta_{\\mathrm{kv}}\\approx\\frac{|\\mathrm{KV}(x)|\\cdot(s_{\\mathrm{bf16}}-s_{\\mathrm{q}})}{s_{\\mathrm{bf16}}},\\qquad t_{\\mathrm{decode}}\\approx t_{\\mathrm{prefill}}(1-h_{\\mathrm{cache}})+t_{\\mathrm{step}}N_{\\mathrm{out}}$$</div>\n<p>式中 Δ<sub>kv</sub> 为量化释放的 KV 余量，s 为每元素字节数，h<sub>cache</sub> 为前缀缓存命中率，N<sub>out</sub> 为补全 token 数。该式揭示两个失效条件：其一，若版本错配使 h<sub>cache</sub> 塌缩，预填项 t<sub>prefill</sub>(1−h<sub>cache</sub>) 会吞掉量化省下的显存收益，解码时延突破 SLO；其二，若策略层为追求奖励而扩张上下文集合，即使单元素精度降到 FP8，|KV(x)| 仍可能越界，截断被迫回退，跨文件证据被丢弃，补全可用性下降。工程判断是：量化档位应作为策略动作空间的一部分，而非部署侧的静态配置。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>缓存版本错配</td><td>文件路径命中但版本不同</td><td>错误 KV 复用污染补全，或强制重预填推高时延</td></tr><tr><td>量化噪声放大</td><td>NVFP4 用于长尾标识符生成</td><td>补全采纳率下降，奖励信号失真</td></tr><tr><td>截断与量化脱钩</td><td>先截断后量化，未联合求解</td><td>KV 余量闲置或越界，SLO 与质量双损</td></tr></tbody></table>\n<p>具体例子：一次补全请求携带当前文件与三个跨文件依赖片段，若以 BF16 驻留恰好触及 B<sub>kv</sub> 上限，切换到 FP8 后余量可再纳入一个依赖片段，但该片段的标识符若在 NVFP4 下量化，草稿模型生成的候选可能与仓库真实符号不一致，验证阶段被拒，奖励稀疏化。此时投机解码的草稿一致性未被材料验证，加速收益可能被验证失败抵消。因此在该方案的边界内，精度选择应优先保证前缀缓存键与文件版本严格对齐，再在 FP8 档位上做上下文扩张，NVFP4 仅用于对量化不敏感的权重侧；任何把奖励等同于离线指标的部署，都会掩盖版本错配与量化噪声在真实编辑流中的累积代价。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-19\">十九 · 显存账本的三本账：权重、激活、KV</h3>\n<p>在 Blackwell 上给仓库级补全做容量规划，第一件事不是选框架，而是把显存拆成三本互不挪用的账。权重账是静态的：参数量乘以每参数字节数，NVFP4 下每参数 0.5 字节（含块缩放因子开销略高），FP8 下 1 字节，BF16 下 2 字节。激活账是瞬态的：预填阶段随 batch×seqlen 线性增长，解码阶段被压到极小但受并行切分影响。KV 账才是仓库级补全的真正矛盾点——它随并发请求数与上下文长度双向膨胀，且被前缀缓存策略反复改写。</p>\n<p>三本账不能混算。工程上常见的错误是用“总显存减去权重”当作 KV 可用量，忽略预填峰值激活与通信缓冲区。在 GB200 NVL72 这类整机柜形态里，单 GPU 的 HBM3e 容量是固定的，权重按张量并行切分后每卡占用下降，但 KV 若按请求维度复制（数据并行或注意力头切分不当）则不会同步下降。因此预算必须写成：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\underbrace{\\frac{P\\cdot b_w}{N_{\\text{tp}}}}_{\\text{权重}} + \\underbrace{A_{\\text{prefill}}(B,S)}_{\\text{激活峰值}} + \\underbrace{\\frac{2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot S\\cdot B_c\\cdot b_{kv}}{N_{\\text{tp}}}}_{\\text{KV}} + M_{\\text{comm}}$$</div>\n<p>其中 $L$ 为层数、$H_{kv}$ 为 KV 头数、$d_h$ 为头维、$S$ 为上下文长度、$B_c$ 为并发序列数、$b_{kv}$ 为 KV 每元素字节数、$M_{\\text{comm}}$ 为 NCCL/NIXL 缓冲与框架预留。这个式子的每一项都可复算，但每一项的取值都由推理机制而非硬件参数决定。</p>\n<p>具体例子：一个 70B 级解码器在 FP8 权重下每卡（8 卡 TP）约 8.75 GB 权重；若上下文 32K、KV 头 8、头维 128、80 层、FP8 KV，则单序列 KV 约 2×80×8×128×32768×1 B ≈ 5.4 GB。并发 8 条即 43 GB KV，加上预填激活与通信缓冲，单卡 80 GB 级 HBM3e 已接近饱和。这说明仓库级补全的并发上限不是由算力决定，而是由 KV 账决定。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-20\">二十 · 分页与碎片：为什么连续分配会杀死命中率</h3>\n<p>前缀缓存以文件路径与版本为键复用 KV，这一机制要求缓存块可被独立索引、独立释放、独立复用。若按序列连续分配 KV，一个被截断的跨文件片段会留下无法回收的尾部空洞；当编辑流中文件版本频繁变更，旧版本 KV 失效但物理页仍被占用，碎片率随会话时长单调上升。分页 KV（PagedAttention 一类机制）把 KV 切成固定 token 数的块，用块表映射逻辑位置到物理页，使失效块可立即归还池，命中块可跨请求共享。</p>\n<p>代价在间接寻址。每次注意力读取需经块表翻译，块表本身占显存（每序列每块一个表项），且块尺寸越小碎片越少但表项越多、访存越不连续。工程判断是：仓库级补全的上下文片段长度分布不均，跨文件依赖片段常为数百 token 量级，块尺寸取 16 或 32 token 能在碎片率与表开销间取得平衡；块太小会让块表查询成为解码阶段的额外延迟源。</p>\n<p>伪代码思路：请求到达时先按文件路径+版本哈希查块表，命中则把共享块引用计数加一，未命中则从空闲池取页并触发预填；请求结束时引用计数归零的块回池。引用计数是防止“一个请求释放了仍被其他请求共享的块”的关键，缺失它会导致复用错误 KV 并污染补全结果——这正是版本错配之外的第二类缓存污染路径。</p>\n<p>带宽代价：分页使 KV 读取从大块连续访存变为按块 gather，HBM3e 的高带宽只有在足够大的连续事务下才能吃满。块尺寸过小会让有效带宽下降，解码阶段每 token 的 KV 读取时间上升，直接体现为 TPOT 恶化。因此在低延迟补全 SLO 下，分页的收益必须用命中率提升摊薄掉 gather 开销，否则不如退回大块连续分配。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-21\">二十一 · 压缩与复用：KV 量化、结构压缩与跨请求共享</h3>\n<p>KV 压缩有三条正交路径，仓库级补全要按上下文价值分配而非一刀切。第一条是数值压缩：KV 以 FP8 存储，每元素 1 字节，相对 BF16 减半；NVFP4 进一步压到 0.5 字节但需块缩放，对注意力输出的数值扰动更大，需验证补全质量。第二条是结构压缩：按头或按层丢弃低贡献 KV，或对跨文件片段做 token 级剪枝——这与上下文组织层的截断策略直接耦合，截断发生在预填前，剪枝发生在预填后，两者都在争同一个 KV 预算。第三条是跨请求复用：前缀缓存本质上是 KV 共享，同一文件版本被多个补全请求引用时只存一份。</p>\n<p>复用的收益可写成命中率函数。设请求上下文总长为 $S$，命中前缀长为 $S_h$，则预填计算量按 $(S-S_h)$ 计，解码时延中预填部分被摊薄：</p>\n<div class=\"formula\">$$t_{\\text{req}} \\approx \\frac{(S-S_h)\\cdot c_{\\text{prefill}}}{} + S_{\\text{out}}\\cdot t_{\\text{tpot}},\\qquad \\text{命中率}\\ \\rho=\\frac{\\sum S_h}{\\sum S}$$</div>\n<p>这里 $c_{\\text{prefill}}$ 是每 token 预填代价，随模型与并行切分变化。关键判断是：$\\rho$ 的提升不是免费的，它要求缓存池足够大以容纳多版本文件 KV，而池容量与并发 KV 争同一块 HBM。当编辑流中文件版本更迭快，缓存池会被旧版本占满而命中率反而下降，此时需要按版本新鲜度做淘汰，而非简单 LRU。</p>\n<p>具体例子：一个仓库会话中，当前文件被反复编辑而依赖文件稳定。依赖文件的 KV 应长期驻留并跨请求共享，当前文件的 KV 每次编辑即失效。若系统对所有文件一视同仁地 LRU，稳定依赖文件会被频繁编辑的当前文件挤出，命中率崩塌。按“路径稳定性×引用频次”加权的淘汰策略，比纯 LRU 更契合仓库编辑流的访问模式。</p>\n<p>带宽瓶颈在此处显形：解码阶段每生成一个 token 需读取全部历史 KV，KV 压缩直接降低每 token 的字节读取量，从而提升可支持的并发数；但压缩引入的反量化计算会占用 SM 周期，在算力已近饱和时可能得不偿失。Blackwell 的 tcgen05 与 TMEM 路径对低精度矩阵乘友好，KV 以 FP8 存储并在 MMA 中直接消费可避免显式反量化，这是压缩真正兑现带宽收益的前提。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-22\">二十二 · 卸载：把冷 KV 放到哪里，代价是什么</h3>\n<p>当 KV 账超出 HBM，卸载是唯一出路，但卸载路径的选择决定 SLO 能否守住。可选层级是：HBM → 主机 DRAM（经 PCIe/C2C）→ 本地 NVMe → 远端存储（经 NIXL 或网络文件系统）。每一级的带宽与延迟差一个数量级以上，因此卸载策略必须是“按访问概率分层”，而非“满了就往下赶”。</p>\n<p>仓库级补全的访问模式给了分层依据：稳定依赖文件的 KV 被高频复用，应留在 HBM；当前文件的历史版本 KV 只在少数回滚场景被访问，可下沉到主机 DRAM；跨会话的仓库快照 KV 访问稀疏，适合 NVMe。卸载的代价是恢复时的预填或拷贝：从 DRAM 取回 KV 经 PCIe 的带宽远低于 HBM，若一次补全请求需要恢复大量 KV，恢复时间会直接击穿低延迟约束。因此卸载粒度应与分页块对齐，只取回命中块而非整段上下文。</p>\n<p>工程判断：卸载的收益只在“被卸载 KV 的复用间隔足够长、且恢复量足够小”时成立。若某文件的 KV 每隔几个请求就被再次命中，卸载再取回的往返开销超过它占用的 HBM 机会成本，应保留在 HBM。这要求监控卸载命中率与恢复延迟两个指标，而非只看 HBM 占用率。</p>\n<p>功耗维度也需计入：HBM 与 DRAM 的每字节访问能耗差异显著，频繁跨层搬运会抬高整机功耗；在 GB200 NVL72 这种高密度机柜里，功耗预算与散热上限会反过来约束卸载频率。卸载不是免费的容量扩展，而是用带宽与功耗换容量。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-23\">二十三 · 可复算的显存预算：一个完整算例</h3>\n<p>下面给出一个可逐步复算的预算表，所有输入均为可调参数，读者可按自己的模型与 SLO 替换。假设：解码器 32B 参数、80 层、KV 头 8、头维 128、FP8 权重与 FP8 KV、8 卡张量并行、单卡 HBM3e 容量记为 $C$、目标并发 $B_c$、上下文上限 $S$。</p>\n<table class=\"mini\">\n<thead><tr><th>账目</th><th>计算式</th><th>数值（示例参数）</th></tr></thead>\n<tbody>\n<tr><td>权重</td><td>$P\\cdot b_w / N_{tp}$</td><td>32e9×1 B / 8 = 4.0 GB</td></tr>\n<tr><td>单序列 KV</td><td>$2LH_{kv}d_h S b_{kv}$</td><td>2×80×8×128×32768×1 B ≈ 5.37 GB</td></tr>\n<tr><td>并发 KV</td><td>单序列 KV × $B_c$</td><td>$B_c$=8 时 ≈ 43.0 GB</td></tr>\n<tr><td>预填激活峰值</td><td>$A_{\\text{prefill}}(B,S)$</td><td>按框架实测，量级数 GB</td></tr>\n<tr><td>通信与预留</td><td>$M_{\\text{comm}}$</td><td>NCCL/NIXL 缓冲，量级数 GB</td></tr>\n<tr><td>合计</td><td>四项之和</td><td>须 ≤ $C$</td></tr>\n</tbody>\n</table>\n<p>复算路径：先由 $C$ 减去权重与预留，得到 KV+激活可用量；再由单序列 KV 除之，得到理论最大并发；最后用预填激活峰值校验该并发下预填阶段是否仍放得下。若理论并发低于 SLO 所需并发，则必须走压缩（KV 量化到 NVFP4 使单序列 KV 减半）或卸载（把冷文件 KV 下沉），或降低 $S$ 由上下文组织层截断。三者之中，截断对补全质量影响最直接，压缩需验证数值，卸载需验证恢复延迟——这正是强化学习策略层要联合优化的对象：在 $|\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}}$ 与 $t_{\\text{decode}}\\le t_{\\text{SLO}}$ 的约束下选择哪些跨文件证据进入上下文。</p>\n<p>该算例的工程含义是：32B 级模型在 32K 上下文、8 并发下，KV 已是权重账的十倍以上，容量瓶颈完全在 KV 侧。这也解释了为何前缀缓存命中率是仓库级补全的第一指标——命中一个长依赖片段，等于省下数 GB 的重复 KV 与对应的预填时间。而版本错配会让这份节省归零并触发重新预填，因此缓存键必须包含文件内容哈希而非仅路径与时间戳。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-24\">二十四 · 带宽瓶颈定位与监控口径</h3>\n<p>显存账算清之后，下一个问题是瓶颈在容量还是在带宽。解码阶段是典型的带宽受限：每 token 需读取权重一次加全部 KV，算术强度极低，HBM3e 带宽决定 TPOT 下限。预填阶段是算力受限：大矩阵乘的算术强度高，tcgen05 与 2-SM MMA 的利用率决定预填吞吐。仓库级补全的负载恰恰是“短解码、长预填”的组合，因此系统瓶颈随请求阶段切换而漂移。</p>\n<p>定位方法：分别测预填吞吐（token/s）与解码 TPOT，再看前缀缓存命中率。若命中率高而 TPOT 仍差，瓶颈在解码带宽或分页 gather 开销；若命中率低而预填吞吐高，瓶颈在缓存池容量与淘汰策略；若两者都正常但端到端延迟超标，瓶颈在调度排队与批组成，而非显存。监控必须同时覆盖 KV 占用、命中率、块表开销、卸载恢复延迟与预填激活峰值，单看 HBM 占用率会掩盖真实瓶颈。</p>\n<p>一个具体判断：当 KV 以 FP8 存储且命中率稳定时，解码带宽瓶颈的缓解手段是提高并发以摊薄权重读取，但这会推高 KV 账；当 KV 账已满，提高并发反而触发卸载与恢复，TPOT 恶化。因此并发上限应由 KV 预算反推，而非由算力或调度器拍定。强化学习策略层若能把“哪些上下文值得驻留”学准，等价于在同样的 HBM 下提高有效命中率，这是该论文机制与显存账本的交汇点：策略输出直接决定 KV 预算的分配对象，而预算约束反过来塑造策略的可行域。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-25\">二十五 · 从补全请求到批的成形：连续批处理为何是默认解</h3>\n<p>仓库级补全的请求到达方式决定了调度器的第一层形态。编辑器在光标处触发请求，携带当前文件、光标位置与仓库快照的版本标识；上下文组织层随后挑选跨文件片段并截断到 KV 预算内。这一串动作意味着请求的“形状”在到达时并不固定：同一份仓库快照下，不同光标位置命中的跨文件证据数量不同，提示长度因此抖动。静态批处理在这种抖动下会退化为“按最长请求对齐”，短请求被迫等待长请求的预填与解码完成，GPU 利用率与尾延迟同时恶化。连续批处理（continuous batching）把批的成员资格从“请求级”下沉到“迭代级”：每个解码步重新组装当前活跃请求集合，完成的请求立即退出、新到的请求立即插入，批大小在每一步动态变化。</p>\n<p>机制上，调度器维护两个队列：等待预填的请求与正在解码的请求。每个解码步，调度器按 token 预算（而非请求数）决定本轮纳入哪些请求，因为解码阶段的算力消耗与批内 token 总数成正比，而 KV 读取带宽与批内序列长度分布相关。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{step}: \\quad \\mathcal{B}_{t+1} = \\mathrm{Select}\\big(\\mathcal{Q}_{\\text{decode}} \\cup \\mathcal{Q}_{\\text{prefill}},\\ \\text{budget}_{\\text{tok}}\\big),\\quad \\text{evict}\\ \\{r \\mid r.\\text{finished}\\}$$</div>\n<p>对补全场景，这个预算要额外挂一个时延约束：单步解码的墙钟时间必须让最老请求的剩余时延落在 SLO 内。工程代价体现在两处。其一是调度开销本身——每步重组批需要重新计算位置编码偏移、注意力掩码与 KV 页表映射，在 Blackwell 上这些是 host 侧与 device 侧的同步点，批越小、重组越频繁，开销占比越高。其二是显存碎片：请求进出导致 KV 页的分配与回收频繁，若按请求粒度分配连续 KV，碎片会吞掉本可用于跨文件上下文的预算。因此连续批处理在实践中几乎总与分页 KV（paged KV cache）绑定，把 KV 切成固定大小的页，按需映射，页表成为调度器与注意力核之间的契约。</p>\n<p>具体例子：一个补全请求命中三个跨文件片段，提示长度约等于当前文件加两段依赖；紧随其后到达的请求只命中一个片段。静态批会让后者等待前者预填完毕；连续批则让后者在第一步就插入解码批，前者的预填在后续步中分块推进。代价是前者的预填被拉长，若其 SLO 更紧，就需要优先级机制介入——这正是下一节的问题。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-26\">二十六 · chunked prefill：把长预填切碎，换取解码步的稳定节奏</h3>\n<p>仓库级补全的长上下文预填是时延的主要来源。前缀缓存命中时，已编码文件版本的 KV 直接复用，未命中部分才需要重新预填；但版本错配或新文件首次出现时，预填量会突然抬升。若把整段预填塞进一个解码步，该步的算力与带宽需求远超其余步，形成周期性尖峰，批内其他请求的解码被拖慢，尾延迟被这个尖峰定义。chunked prefill 把预填按 token 数切成若干块，每块与当前解码批合并执行，使每步的计算量趋于平坦。</p>\n<p>切块大小的选择是一个显存—时延的联合优化。设块大小为 $c$，解码批内已有 $n$ 条序列、平均上下文长度 $\\bar{L}$，则单步 KV 读取量近似为 $n\\bar{L} + c$ 个 token 对应的 KV，而算力需求由 $c$ 的注意力计算主导。块太大则单步尖峰回归；块太小则预填被切得过碎，每块都要重读页表与前缀元数据，固定开销摊不薄。工程判断是让 $c$ 与解码批的 token 预算同量级，使预填与解码在同一内核启动中共享内存搬运。</p>\n<p>对补全 SLO 的直接后果：chunked prefill 不降低总预填量，但把预填的时延分布从“一次长阻塞”变成“多次短占用”，使解码请求的步间间隔可控。代价是预填请求自身的完成时延被拉长——一个需要全量重预填的请求可能跨越多个解码步才完成，若该请求的 SLO 比解码请求更紧，就必须给它更高的调度权重。另一个代价是前缀缓存的写入时机：分块预填意味着 KV 是渐进写入的，若在写入完成前就有同版本文件的请求到达，缓存键的可见性需要原子化处理，否则会出现半成品 KV 被复用、污染补全结果的失败模式。这与版本错配属于同一类风险，只是触发条件从“版本不同”变成“版本相同但尚未写完”。</p>\n<p>具体例子：某文件被编辑后首次触发补全，前缀缓存未命中，需重预填整段上下文。若不切块，该步阻塞其余解码请求；切块后，该请求的预填分摊到数个解码步，其余请求的步间间隔保持稳定，而该请求自身的首 token 时延上升。调度器需要判断：这次补全的用户是否在等待——若是交互式补全，首 token 时延优先；若是后台校验类请求，吞吐优先。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-27\">二十七 · 优先级与抢占：奖励信号如何变成调度权重</h3>\n<p>论文的强化学习目标把补全可用性与上下文预算、解码时延绑在一起：策略在有限 KV 预算内选择跨文件证据，奖励来自补全被采纳或通过校验。这个奖励结构对调度有一个直接推论——不同请求的“价值密度”不同。命中高价值跨文件证据、且历史采纳率高的请求，其补全被采纳的概率更高；反之，上下文稀疏、证据噪声大的请求，即使占用同样 KV 预算，期望奖励更低。调度器可以把这种价值密度作为优先级权重，而不必等奖励回传后再调整。</p>\n<p>优先级机制需要与抢占配套，否则高优先级请求到达时只能排队。抢占的粒度决定代价：按请求抢占意味着被抢占请求的 KV 必须换出到 host 内存或丢弃重算；按页抢占则只换出部分 KV 页，保留前缀缓存中已命中的部分。后者对补全场景更友好，因为跨文件片段的 KV 往往被多个请求共享，整请求换出会破坏共享页的引用计数。换出代价是 PCIe 带宽与 host 内存占用；重算代价是预填算力。在 Blackwell 上，NVLink 5 的机架内带宽让 KV 在 GPU 间的迁移比换出到 host 更便宜，因此抢占策略在 NVL72 拓扑下倾向于把被抢占请求迁到另一颗 GPU 继续解码，而非降级到 host。</p>\n<p>公式上，优先级可以写成期望奖励与紧迫度的乘积，紧迫度由剩余时延裕度决定：</p>\n<div class=\"formula\">$$\\text{prio}(r) = \\hat{r}(r)\\cdot \\frac{1}{\\max(\\epsilon,\\ t_{\\text{SLO}}(r) - t_{\\text{elapsed}}(r))}$$</div>\n<p>其中 $\\hat{r}(r)$ 是策略对本次补全采纳概率的估计，可由上下文组织层给出的证据质量与历史采纳统计近似。这个式子的工程含义是：临近 SLO 的低价值请求也会被抬升优先级，避免尾延迟被“不重要但快超时”的请求拉爆。代价是优先级估计本身可能失准——奖励稀疏且依赖用户采纳，$\\hat{r}$ 的方差大，错误的优先级会导致高价值请求被低价值请求挤占 KV 预算，反而降低整体采纳率。这是策略层与调度层耦合的固有风险，缓解手段是把优先级限制在有限档位而非连续值，减少估计误差的放大。</p>\n<p>具体例子：两个请求同时到达，一个命中主依赖文件的当前版本、历史采纳率高，另一个只命中编辑历史中的弱相关片段。前者获得更高优先级并占据前缀缓存命中页；后者在 KV 预算紧张时被延后预填。若后者恰是用户正在等待的交互式补全，调度器需要靠紧迫度项把它拉回，否则会出现“高价值但非当前焦点”的请求饿死交互请求的尾延迟问题。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-28\">二十八 · 分离式预填/解码：把两种资源需求拆到不同池</h3>\n<p>预填与解码对硬件的需求结构不同。预填是算力密集型：大矩阵乘、长序列注意力，受 Tensor Core 吞吐与 SM 占用约束；解码是带宽密集型：每步只算一个 token，但要把整段 KV 从显存读一遍，受 HBM 带宽约束。把两者放在同一批里，chunked prefill 只是让它们在时间上交错，资源争用依然存在——预填的算力尖峰与解码的带宽需求在同一组 SM 上竞争。分离式预填/解码（disaggregated prefill/decode）把两个阶段放到不同的 GPU 池：预填池负责把提示编码成 KV，解码池负责自回归生成，KV 通过 NVLink 或 RDMA 从预填池传到解码池。</p>\n<p>对仓库级补全，这个拆分的收益点在前缀缓存的归属。跨文件片段的 KV 由预填池生成并被多个请求共享，若缓存放在预填池侧，解码池按需拉取命中页，则缓存的复用范围不再受单卡显存限制，而是受池间带宽限制。代价是 KV 传输本身：一段长上下文的 KV 体积与序列长度、层数、头数成正比，传输时延会叠加到首 token 时延上。工程判断是只传命中页与本次请求实际需要的页，未命中的跨文件片段在预填池侧按版本键缓存，避免重复预填。</p>\n<p>拓扑上，GB200/GB300 NVL72 的机架内 NVLink 5 让池间 KV 传输的带宽远高于跨机架 RDMA，因此分离式部署在机架尺度内更划算；跨机架则要权衡传输时延与预填池的利用率。另一个代价是调度复杂度：两个池的批处理策略需要协同，预填池的 chunk 大小影响解码池的等待时间，解码池的批大小影响 KV 拉取的聚合效率。若两池独立调度，容易出现预填池空闲而解码池排队、或反之的错配。</p>\n<p>具体例子：一个请求的上下文包含三个跨文件片段，其中两个的版本已在预填池缓存中。预填池只重算未命中的那个片段，把三段 KV 按页表拼好后传给解码池；解码池在本地批中插入该请求，开始生成。若传输时延超过解码池当前批的步间间隔，该请求的首 token 时延被传输定义，此时应优先把缓存页预取到解码池侧，而非等请求到达再传。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-29\">二十九 · 尾延迟怎么压：从 P99 反推调度参数</h3>\n<p>补全场景的 SLO 通常挂在尾延迟上，而非平均时延。尾延迟的来源可以分解为：预填阻塞、批内长请求拖尾、KV 换出与重算、缓存版本错配触发的重预填。逐项压制的手段不同。预填阻塞靠 chunked prefill 与优先级；批内长请求拖尾靠连续批处理让短请求先完成，但要注意解码步的 token 预算若被长请求占满，短请求仍会被拖；KV 换出靠分页与共享页引用计数，避免整请求级换出；版本错配靠缓存键的原子可见性与版本校验，把“复用错误 KV”从时延问题降级为正确性问题单独处理。</p>\n<p>从 P99 反推参数的做法是：给定 SLO 时延 $t_{\\text{SLO}}$，把预算拆成预填、排队、解码三段，每段留出裕度。解码段的步数由补全长度决定，补全通常短，步数少，因此解码段预算主要被步间间隔占据；步间间隔由批内最大 token 数与 KV 读取量决定。预填段预算决定 chunk 大小与是否允许全量重预填。排队段预算决定优先级档位与抢占阈值。三段的裕度不能平均分配——尾延迟由最慢的那一段定义，裕度应集中在方差最大的段，通常是预填段，因为缓存命中率波动直接改变预填量。</p>\n<p>监控项对应这些段：前缀缓存命中率、重预填触发次数、批内 token 数分布、KV 换出量、步间间隔的 P99。失败模式在这些监控上表现为：命中率下降但重预填次数不升，说明版本键设计有问题，缓存被无效化；步间间隔 P99 抬升而批内 token 数未变，说明 KV 读取量因碎片或页表映射变差；换出量上升而采纳率不变，说明优先级把 KV 预算给了低价值请求。</p>\n<p>具体例子：某时段补全请求的 P99 时延抬升，监控显示前缀缓存命中率稳定、批内 token 数稳定，但 KV 换出量上升。追查发现优先级权重把大量弱相关上下文请求抬到了高优先级，挤占了共享页的驻留空间，导致高价值请求的命中页被换出后重预填。修正手段是给优先级加一个证据质量下限，弱证据请求不得抢占共享页，代价是这类请求的时延上升，但尾延迟由高价值请求定义，整体 SLO 反而收敛。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-30\">三十 · 调度与策略的耦合边界：奖励回传不能直接当调度信号</h3>\n<p>论文的奖励来自补全被采纳或通过校验，回传后更新上下文选择与生成策略。一个常见的工程误判是把回传奖励直接当作调度优先级，理由是“被采纳的请求价值高”。问题在于奖励的时序：采纳信号在补全返回编辑器之后才产生，而调度决策在请求到达时就已做出；用滞后信号做即时调度，等于用上一轮的结果预测这一轮的价值，在编辑流快速变化时失准。更稳的做法是把奖励用于更新上下文组织层的证据排序，让高采纳率的跨文件片段在后续请求中更早进入提示与前缀缓存，调度层只消费这个排序结果，不直接消费奖励值。</p>\n<p>这个边界的代价是策略更新的延迟被拉长：证据排序的修正要经过若干请求才能体现在缓存命中率上，期间调度层仍按旧排序分配 KV 预算。若编辑流在这段窗口内发生大改（例如主依赖文件被重写），旧排序会把预算分配给已失效的片段，触发版本错配与重预填。缓解手段是把版本标识纳入排序键，版本变更即降权，不等奖励回传。这与前缀缓存按文件路径与版本做键复用是同一套版本语义，只是作用在排序而非缓存查找上。</p>\n<p>另一个耦合点是投机解码。草稿模型先出候选再验证，能压低解码段时延，但草稿模型与仓库上下文的一致性未在材料中给出验证。若草稿模型基于截断后的上下文出候选，而验证用的目标模型看到的是完整上下文，接受率会因上下文不一致而下降，验证开销反而抬升尾延迟。调度层能做的是把草稿模型的上下文视图与目标模型对齐，即两者消费同一份前缀缓存页表，避免各自截断。代价是草稿模型也要占用 KV 预算，在预算紧张时与跨文件上下文争夺同一批页。</p>\n<p>具体例子：一个请求的上下文组织层按旧排序把弱相关片段排在前面，前缀缓存命中该片段但版本已过期，重预填被触发；同时草稿模型基于这段过期上下文出候选，验证阶段目标模型拒绝多数候选，解码步数上升。两个代价叠加，尾延迟突破 SLO。修正落在排序键的版本语义与草稿模型的上下文对齐上，而非调度参数本身——这说明调度只能压制时延的分布形状，不能修复上游上下文组织的错误。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-31\">三十一 · 从单卡到多卡：补全请求在并行维度上的落点</h3>\n<p>仓库级补全的推理拓扑不是自由选择的，而是被三个约束挤压出来的：前缀缓存按文件路径与版本做键，KV 条目必须与请求同址；解码时延受 SLO 硬约束，任何跨节点往返都要计入首 token 与后续 token 的预算；跨文件上下文长度随仓库规模浮动，单卡 HBM 装不下全量候选片段。于是并行切分的第一刀落在<b>数据并行（DP）</b>：每个副本持有完整权重、独立处理不同编辑会话的补全请求，副本间不通信，只在负载均衡层做请求路由。DP 的代价是权重与 KV 的显存复制——B200 单卡 HBM 容量有限，若每个副本都要驻留长上下文 KV，副本数就被显存而非算力卡住。第二刀是<b>张量并行（TP）</b>：把注意力的头维与 MLP 的中间维切开，单层内做 All-Reduce。TP 度越大，单卡权重与激活越小，但每层两次集合通信的延迟直接叠加到解码步上；补全场景 token 数少、批小，TP 的通信开销摊不薄，通常只在单卡放不下权重或需要压单请求延迟时启用。第三刀是<b>流水并行（PP）</b>：按层切分，适合权重极大但请求稀疏的部署，代价是流水气泡——补全请求短、批小，气泡占比高，PP 在低延迟补全里往往是最后手段。第四刀是<b>专家并行（EP）</b>：MoE 结构下把专家分散到不同卡，每层做 All-to-All 把 token 路由到所属专家。EP 的通信量与激活的 token 数乘以路由扇出成正比，补全请求的 token 少，All-to-All 的固定开销占比反而上升。</p>\n<p>把这四维写成约束更直观。设单副本权重显存为 \\(W\\)、单请求 KV 为 \\(K\\)、可用卡数为 \\(N\\)、单卡容量为 \\(M\\)，则可行的切分满足：</p>\n<div class=\"formula\">$$N_{\\mathrm{DP}}\\cdot N_{\\mathrm{TP}}\\cdot N_{\\mathrm{PP}}\\le N,\\qquad \\frac{W+K\\cdot b}{N_{\\mathrm{TP}}\\cdot N_{\\mathrm{PP}}}\\le M$$</div>\n<p>其中 \\(b\\) 是并发批大小。补全场景的 \\(b\\) 小、\\(K\\) 大，不等式右侧被 KV 主导，于是工程上常见的选择是“DP 拉满、TP 取最小可行值”，把显存压力交给前缀缓存淘汰与 KV 量化，而不是交给 TP 的通信。一个具体例子：GB200 NVL72 机架内 72 个 GPU 通过 NVLink 5 域互联，若把 8 路 DP 副本各配 4 路 TP，则每个 TP 组内每层要做两次 All-Reduce，组间零通信；请求路由只需保证同一编辑会话的连续补全落在同一 DP 副本上，否则前缀缓存键虽在、KV 却在别的副本里，命中率归零。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内带宽决定了切分粒度</h3>\n<p>Blackwell 世代的机架级互联把“哪些并行维度可以便宜地做”这件事重新划了线。NVLink 5 提供 GPU 间高带宽直连，NVSwitch 把机架内 GPU 组成全互联域，使得 TP 与 EP 的集合通信不必出域、不必经过 InfiniBand。判断切分粒度的准则很直接：<b>通信密集的维度放在 NVLink 域内，通信稀疏的维度跨域</b>。TP 的 All-Reduce 每层都发生，必须留在域内；EP 的 All-to-All 每层发生且扇出大，也应留在域内；PP 只在 stage 边界传激活，可以跨域；DP 完全不通信，放哪都行。这条准则的代价面是：域内带宽再高也不是无限，All-Reduce 的耗时随消息大小与环/树算法变化，TP 度越大、单次归约的数据量越小但次数不变，延迟被固定开销主导。补全请求的解码步多、每步消息小，TP 的通信延迟几乎无法被计算掩盖，这正是小批低延迟场景对 TP 保守的原因。</p>\n<p>用带宽-计算比对通信是否可隐藏：设单层计算量为 \\(F\\) 次浮点运算、有效算力为 \\(P\\)、单层需搬运的激活字节数为 \\(S\\)、互联带宽为 \\(B_w\\)，则计算时间 \\(t_c=F/P\\)、通信时间 \\(t_m=S/B_w\\)。当 \\(t_m&lt;t_c\\) 时通信可被计算掩盖，否则暴露为延迟。补全解码阶段 \\(F\\) 极小（单 token 的矩阵乘），\\(t_c\\) 短，\\(t_m\\) 很容易反超——这是“通信什么时候成为瓶颈”的第一条判据：<b>解码步的计算强度不足以掩盖集合通信</b>。预填阶段则相反，长上下文的 \\(F\\) 大，TP 的 All-Reduce 可被掩盖，所以同一套 TP 拓扑在预填与解码上的性价比完全不同。工程上的直接推论是分离式预填/解码：预填放在大 TP、高算力利用的池子里，解码放在小 TP、低通信的池子里，两池之间用 KV 传输衔接。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-33\">三十三 · All-Reduce 与 All-to-All：两种通信模式的代价结构</h3>\n<p>All-Reduce 是 TP 的常态。环算法的通信量约为 \\(2\\cdot\\frac{n-1}{n}\\cdot S\\)（\\(n\\) 为参与卡数、\\(S\\) 为消息字节），树算法延迟更低但带宽利用不同；无论哪种，参与卡数增加时单卡搬运量趋近 \\(2S\\)，延迟随跳数增长。对补全而言，关键不是单次 All-Reduce 多快，而是它出现在每个解码步里：步数乘以单步通信延迟就是纯增的时延。若一个补全平均生成数十个 token，TP=4 的每步两次 All-Reduce 就构成可观的固定税。降低这笔税的手段有三条：缩小 TP 度、把权重与 KV 量化到 NVFP4/FP8 以减少消息字节、以及用连续批处理把多个请求的解码步拼在一起让通信摊薄——但补全的 SLO 严格，拼批会拉长单请求时延，摊薄与延迟在这里直接对冲。</p>\n<p>All-to-All 是 EP 的常态，代价结构不同：它的通信量正比于被路由的 token 数乘以每个 token 被送往的专家数，且是<b>非对称、非规则</b>的——路由分布不均时出现热点卡，最慢的那条链路决定整层时间。补全请求 token 少，All-to-All 的固定启动开销占比高；更麻烦的是负载不均，少数专家被大量 token 选中时，热点卡的排队把整批拖住。工程对策是容量因子与 token 丢弃/重路由，但这会改变模型输出，对补全可用性有直接影响——这与论文奖励信号所优化的目标（补全是否被采纳）是同一件事的两面：路由策略的微小偏差会通过生成质量反映到采纳率上。一个具体例子：MoE 解码器在 EP=8 下处理一批补全请求，若某层路由把 60% 的 token 压到两张卡上，该层 All-to-All 的完成时间由这两张卡的入向带宽决定，其余六张卡空转，等效算力利用率被拉低，解码步时延上升。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-34\">三十四 · NIXL 传输：KV 在池间的搬运与它的隐性成本</h3>\n<p>分离式部署把预填与解码拆到不同池后，KV 必须从预填池搬到解码池，这条路径的传输库就是 NIXL 一类点对点传输层。它的价值在于把 KV 块按地址描述符直接搬运，绕过通用网络栈，并支持 GPU 显存到 GPU 显存的直接传输。对补全而言，KV 传输的成本要计入 SLO：设单请求 KV 字节数为 \\(S_{kv}\\)、传输带宽为 \\(B_t\\)、传输启动开销为 \\(t_0\\)，则搬运时间为 \\(t_0+S_{kv}/B_t\\)。长上下文补全的 \\(S_{kv}\\) 大，若跨节点走 InfiniBand，这段搬运可能与解码本身同量级；若在同一 NVLink 域内，带宽高、\\(t_0\\) 小，代价可接受。这解释了为什么分离式预填/解码在机架内（GB200 NVL72 这类 NVLink 域）收益明显，跨机架则要重新核算。</p>\n<p>KV 传输还有一个与论文机制直接相关的陷阱：<b>前缀缓存键与 KV 所在位置必须一致</b>。论文的前缀缓存以文件路径与版本为键，若预填池与解码池各自维护缓存，同一文件版本可能在两处各存一份，版本错配时复用错误 KV 会污染补全结果——这是材料中明确列出的失败模式。NIXL 传输解决的是“KV 怎么搬”，但“搬哪一份、版本对不对”是上下文组织层与缓存键设计的责任。工程判断是：把缓存键的版本校验放在传输发起之前，宁可重新预填也不跨版本复用；同时把 KV 传输的字节数纳入 KV 预算 \\(B_{\\mathrm{kv}}\\) 的核算，因为传输中的 KV 也占着源端显存直到确认送达。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-35\">三十五 · 通信何时成为瓶颈：三条可操作的判据</h3>\n<p>把前面的机制收成可判定的条件，避免“看情况”式的模糊判断。第一条判据是<b>计算-通信比</b>：解码步的单 token 计算量小，TP 的 All-Reduce 延迟无法被掩盖，此时 TP 度每增加一档，单步时延近似线性增加；预填阶段计算量大，同一拓扑下通信可隐藏。第二条判据是<b>批大小与通信摊薄</b>：连续批处理把多请求的解码步拼批，集合通信的消息字节随批增大而增大，但通信次数不变，摊薄效应存在；然而补全 SLO 严格，批越大单请求排队越久，摊薄收益被排队延迟吃掉，存在一个由 SLO 决定的最优批上界。第三条判据是<b>域内外带宽落差</b>：同一集合通信在 NVLink 域内与跨 InfiniBand 的耗时差一个量级，任何把 TP 或 EP 跨域部署的方案都要先证明通信可隐藏，否则应改为域内切分加跨域 DP。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>通信模式</th><th>发生频率</th><th>补全场景下的主要代价</th></tr></thead><tbody><tr><td>DP</td><td>无（仅路由）</td><td>—</td><td>权重与 KV 显存复制，副本数受 HBM 限制</td></tr><tr><td>TP</td><td>All-Reduce</td><td>每层每步</td><td>解码步固定通信税，小批下无法掩盖</td></tr><tr><td>EP</td><td>All-to-All</td><td>每层每步</td><td>路由不均导致热点卡，等效算力利用率下降</td></tr><tr><td>PP</td><td>点对点激活</td><td>stage 边界</td><td>流水气泡，短请求下气泡占比高</td></tr></tbody></table>\n<p>一个具体例子把三条判据串起来：某部署在单机架内用 TP=4 跑解码、DP=8 跑请求路由，前缀缓存命中时解码步时延由 All-Reduce 主导；当仓库编辑流出现突发并发，调度器试图把批从 1 拉到 8 来摊薄通信，结果单请求排队时间超过补全 SLO，采纳率下降——这正是论文奖励信号会惩罚的行为。正确的做法不是继续加批，而是把 TP 降到 2、把省下的卡转成 DP 副本，用显存换通信，同时靠 NVFP4/FP8 量化把 KV 压进单卡预算。这里没有实验数字可引用，材料也未给出硬件档位，所以判断只能落在机制层面：<b>补全的通信瓶颈本质上是“解码步计算强度不足 + SLO 不允许用批换摊薄”两条同时成立</b>，任何并行方案都要先解除其中一条。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-36\">三十六 · 把并行选择接回上下文组织层</h3>\n<p>并行拓扑不是独立决策，它反过来约束上下文组织层能做什么。TP 度决定单卡 KV 预算，KV 预算决定上下文组织层截断跨文件片段的粒度；截断越激进，前缀缓存命中率与补全质量越受影响，而这两者正是强化学习策略要优化的对象。于是出现一个闭环：策略选择哪些跨文件证据进入提示 → 决定 KV 占用 → 决定可行 TP/DP 配比 → 决定通信开销 → 影响解码时延 → 影响补全是否在 SLO 内返回 → 影响采纳奖励。工程上应把这个闭环显式化，在容量规划时把“每请求 KV 字节数”与“域内集合通信延迟”作为两个输入参数，而不是事后调优。对投机解码同样如此：草稿模型与仓库上下文的一致性未在材料中验证，若草稿模型部署在另一并行组，验证阶段的 KV 比对会引入额外传输，抵消投机收益。最终落在一条工程判断上：在 Blackwell 机架内，把通信密集的 TP/EP 锁在 NVLink 域内、把 DP 作为扩展主轴、把 KV 传输的版本校验前置，是让论文这套上下文选择策略在低延迟补全 SLO 下不被通信税吞掉的前提。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-37\">三十七 · 精度塌陷：奖励漂移与策略过拟合的现场</h3>\n<p>仓库级补全的“精度塌陷”不是传统意义上的模型精度掉点，而是补全采纳率在编辑流中持续下滑却难以归因。RL 策略把跨文件上下文选择与生成联合优化，奖励来自采纳或校验通过；一旦奖励信号被稀疏化，策略会向少数高频上下文形态收敛，长尾文件路径上的补全质量随之塌陷。诊断的关键是把“策略输出”与“推理路径”解耦：同一请求分别用当前策略与冻结基线策略跑一遍，比较上下文组织层选出的片段集合差异、前缀缓存命中键差异与最终补全的编辑距离。若差异集中在上下文选择而非解码器，则问题在策略层；若解码器输出在相同上下文下也退化，则需排查量化或 KV 复用污染。</p>\n<p>机制上，上下文组织层按依赖关系与编辑历史排序并截断到 KV 预算，截断点一旦被策略学会“讨好”高频采纳模式，就会系统性丢弃低频但关键的跨文件证据。可用一个诊断指标刻画塌陷：</p>\n<div class=\"formula\">$$\\mathrm{drift}=\\frac{1}{N}\\sum_{i}\\mathbb{1}\\!\\left[\\mathrm{sel}_{\\pi}(x_i)\\neq \\mathrm{sel}_{\\pi_0}(x_i)\\right]\\cdot \\left(\\mathrm{acc}_{\\pi_0}(x_i)-\\mathrm{acc}_{\\pi}(x_i)\\right)$$</div>\n<p>其中 $\\mathrm{sel}$ 为上下文选择集合，$\\mathrm{acc}$ 为采纳指示。drift 为正且集中在特定文件路径族时，说明策略以牺牲长尾换取头部收益。代价体现在显存与带宽：为做对照诊断需同时驻留两套前缀缓存键空间，KV 占用翻倍，在 B200 单卡上直接压缩可用批大小；工程上应改为按路径族抽样回放，而非全量双跑。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-38\">三十八 · OOM 与 KV 预算击穿：预填峰值而非均值</h3>\n<p>OOM 在低延迟补全里几乎总是预填峰值触发，而不是稳态 KV 占用。前缀缓存未命中时，系统需对当前文件与跨文件片段重新预填，瞬时激活与 KV 写入叠加，形成远高于均值的峰值。RL 策略若倾向选择更长的跨文件证据链，命中率未必同步上升，峰值却被推高。定位方法是给每次请求打上“命中字节数 / 预填字节数 / 峰值 KV”三元组，按分位数而非均值看分布；OOM 前通常伴随预填字节数分位数的抬升而命中率持平。</p>\n<p>约束本身在论文中已形式化：$|\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}}$。工程上应把该约束从“请求级”下沉到“预填阶段级”，即在上下文组织层截断时预留预填余量，而不是等解码器阶段再拒绝。一个可操作的伪代码思路：</p>\n<ul>\n<li>读取候选片段，按依赖强度排序，累计估算 KV 字节；</li>\n<li>当累计值超过 $B_{\\mathrm{kv}}-\\mathrm{reserve}_{\\mathrm{prefill}}$ 时停止纳入，reserve 按当前批内未命中请求数动态放大；</li>\n<li>对已命中前缀的文件版本直接复用，不再计入预填估算；</li>\n<li>若单请求仍超限，降级为“仅当前文件 + 一跳依赖”，并记录降级标记供监控。</li>\n</ul>\n<p>代价是吞吐：reserve 放大等价于主动缩小有效批，连续批处理下批抖动随之出现。GB200 NVL72 机柜内单卡显存虽大，但 KV 预算被多请求共享，峰值治理必须与批调度联动，否则 OOM 会以“偶发单请求击穿”的形式反复出现。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-39\">三十九 · 批抖动与尾延迟：命中率波动的传导链</h3>\n<p>批抖动指连续批处理中批组成频繁突变，导致解码步时间方差放大。根因在缓存命中率的短时波动：编辑流中用户切换文件、保存版本，前缀缓存键（文件路径 + 版本）大量失效，未命中请求涌入同一批，预填与解码混跑，批内最长路径决定步进时间。尾延迟因此不是解码器慢，而是“批内混入了一个高预填请求”。定位应看批级指标：批内未命中请求占比、批内预填 token 总量、批步进时间的 P99 与 P50 之比。</p>\n<p>论文的 SLO 约束 $t_{\\mathrm{decode}}\\le t_{\\mathrm{SLO}}$ 在批场景下应理解为批步进约束而非单请求约束。缓解机制是预填/解码分离的轻量版：把未命中预填请求路由到独立队列，解码批只接纳已驻留 KV 的请求，牺牲少量排队时延换取批步进稳定。代价是显存：分离队列需要额外 KV 暂存区，且预填队列的中间激活峰值独立于解码批，B300 上需按队列深度预留。具体例子：一次跨三个文件的跳转编辑会使三个版本键同时失效，若三个请求落入同一解码批，批步进时间被最长预填主导，尾延迟抬升；分离后解码批步进回到基线，代价是这三个请求各多等一个预填周期。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-40\">四十 · 静默降级：缓存错配与投机不一致</h3>\n<p>最危险的失败模式不报错。前缀缓存以文件路径与版本为键，若版本标识粒度不足（例如仅用修改时间或路径哈希），复用错误 KV 会污染补全结果——输出语法合法但语义指向旧版本符号，用户看到的是“看起来对但不对”的补全。这类静默降级无法靠异常日志发现，只能靠一致性校验：对命中缓存的前缀，抽样重算少量 token 的 KV 并与缓存值比对，偏差超阈值即标记该版本键失效。</p>\n<p>投机解码引入第二类静默降级：草稿模型与仓库上下文的一致性未在材料中给出验证，草稿基于截断后的上下文出候选，验证器基于完整上下文校验，两者上下文视图不一致时接受率虚高而实际质量下降。诊断应记录“草稿上下文哈希 / 验证上下文哈希 / 接受率”三元组，哈希不一致而接受率异常高的组合即为可疑。代价在带宽：一致性抽样重算需要回读 KV，占用显存带宽，与解码争抢；工程上应把抽样频率压到每版本键一次而非每请求一次。</p>\n<p>监控体系因此要分三层：请求层记录采纳率与降级标记，批层记录命中率与步进分位数，键层记录版本失效与一致性偏差。三层对齐后才能区分“策略退化”与“缓存污染”。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-41\">四十一 · 回滚：以版本键为粒度的策略回退</h3>\n<p>回滚不能只回退模型权重，因为 RL 策略作用于上下文选择，污染可能已写入前缀缓存。可操作的回滚单元是“策略版本 + 缓存键空间”的联合快照：策略更新时保留上一版策略与对应缓存键的只读副本，一旦监控触发 drift 阈值或静默降级标记，将请求路由切回旧策略并冻结新键写入，旧键空间继续服务直至自然过期。代价是显存：双键空间并存期间 KV 占用上升，需按流量比例限制并存窗口，例如仅对高频路径族保留旧键。</p>\n<p>回滚判定应绑定具体机制而非感觉：drift 指标越过阈值、批步进 P99 与 P50 之比持续抬升、版本键一致性偏差计数上升，三者任一触发即进入回滚候选。工程判断上，RL 策略的收益依赖前缀缓存命中率与 KV 预算的联合优化，而这两者在真实编辑流中波动大；因此回滚窗口应短于缓存键的自然过期周期，否则旧策略会继承被污染的新键。最终落点是一个具体机制：把策略版本号嵌入缓存键，使“策略切换”等价于“键空间切换”，回滚即路由切换，无需清空缓存，也不必等待全量重预填。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-42\">四十二 · 失效边界：从奖励语义漂移到缓存版本错配</h3>\n<p>这套方案的第一个失效条件不在模型侧，而在奖励语义与推理路径的耦合处。强化学习优化的是<em>补全被采纳或通过校验</em>这一序列级信号，而前缀缓存复用与上下文截断发生在奖励回传之前：一次请求若因版本错配复用了错误 KV，模型仍会生成补全，用户仍可能采纳，奖励仍会回传，于是策略被推向“在错误上下文上也能产出可接受片段”的方向。诊断这类精度塌陷不能只看采纳率，必须把采纳率与缓存命中率做交叉切片——命中率高而采纳率下降，指向上下文组织层排序或截断把低价值片段排进了提示；命中率低而采纳率正常，说明预填开销被摊薄但策略尚未学到跨文件证据的价值。工程上应把每次请求的<em>缓存键版本、截断位置、候选片段来源</em>作为三元组落盘，与奖励信号对齐后再做离线归因，否则奖励稀疏叠加延迟反馈，策略会在噪声里漂移而监控面板上一切正常。</p>\n<p>第二个失效条件是 KV 预算与 SLO 的联合越界。上下文组织层按依赖关系与编辑历史排序后截断到预算内，但截断本身有代价：被截掉的片段若恰好是后续解码的草稿依据，投机解码的草稿模型与仓库上下文一致性就会断裂，验证阶段拒绝率上升，解码时延反而被拖长。设单次请求的端到端时延为</p>\n<div class=\"formula\">$$t_{\\text{e2e}} = t_{\\text{prefill}}\\cdot(1-h) + t_{\\text{decode}}\\cdot(1+\\rho_{\\text{rej}})$$</div>\n<p>其中 $h$ 为前缀缓存命中率，$\\rho_{\\text{rej}}$ 为草稿拒绝比例。命中率提升带来的预填摊薄会被拒绝率上升部分抵消，二者在低延迟补全场景下是同一条曲线上的两个方向。定位手段是把 $t_{\\text{prefill}}$、$h$、$\\rho_{\\text{rej}}$ 分通道打点，而不是只监控端到端 P99；尾延迟抬升若伴随 $\\rho_{\\text{rej}}$ 同步上升，应优先回滚上下文截断策略而非解码器配置。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>定位信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>采纳率缓降、命中率不变</td><td>截断排序把噪声片段前置</td><td>截断位置与奖励相关性</td><td>回退上下文排序版本</td></tr><tr><td>P99 抬升、均值平稳</td><td>版本错配触发重预填</td><td>缓存键版本分布</td><td>冻结缓存键规则</td></tr><tr><td>OOM 间歇出现</td><td>批抖动叠加长上下文驻留</td><td>KV 占用与批大小时序</td><td>收紧 KV 预算上限</td></tr><tr><td>补全静默变短</td><td>解码器在预算压力下截断输出</td><td>输出长度分布漂移</td><td>回退解码约束</td></tr></tbody></table>\n<p>第三个失效是批抖动引发的 OOM 与静默降级。真实编辑流的请求长度随当前文件与跨文件上下文规模变化，小批低时延的补全场景本应稳定，但一旦上下文组织层为提升命中率而放宽单请求 KV 驻留，批内最长请求就会把显存峰值拉高，触发驱逐或拒绝新请求；系统若以降级方式应对——缩短补全长度、跳过草稿验证、降低上下文截断阈值——用户侧看到的是补全变短或变钝，而监控上只表现为吞吐轻微下滑。这类静默降级最难定位，因为没有任何错误码。判断依据是输出长度分布与草稿验证率的联合漂移：二者同时下移即说明降级路径被触发。回滚应分级执行，先冻结上下文组织层的预算放宽开关，再回退解码约束，最后才动量化与并行拓扑；在 Blackwell 档位与量化方案未定的前提下，任何涉及 NVFP4/FP8 的变更都应视为高风险回滚项，需单独灰度。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-43\">四十三 · 口径的第一性问题：这篇论文没有可比的数字</h3>\n<p>读这篇论文的实验部分，第一件要建立的工程判断是：它没有给出可核验的数字结果。材料明确说明未提供数据集规模、基线名称、通过率、采纳率、延迟或吞吐的具体数值，也未给出硬件档位与并行拓扑。这意味着任何“提升 X%”的转述都是编造。对工程读者而言，正确的读法是把它当作<strong>机制论文</strong>而非<strong>性能论文</strong>：它主张的是把上下文选择与生成质量联合优化这一建模方式，而不是某个可复现的加速比。因此本部分的“基准与口径”讨论的不是它的实验设置，而是<strong>如果你要在 Blackwell 上复现或评估这类方法，必须自己建立哪一套口径</strong>，以及哪些跨论文的数字根本不可比。</p>\n<p>先明确不可比的三类来源。第一类是<strong>负载口径</strong>：仓库级补全的请求长度由当前文件与跨文件上下文规模决定，材料未给出分布；不同论文若一个按单文件短上下文测、一个按多文件长上下文测，TTFT 与 TPOT 不在同一坐标系。第二类是<strong>奖励口径</strong>：本文奖励来自补全是否被采纳或通过校验，这是在线信号；若另一篇用离线 pass@k 或编辑距离，二者衡量的对象不同，不能相减。第三类是<strong>硬件口径</strong>：材料未给档位，B200 与 GB200 NVL72 在显存带宽、NVLink 域规模、可驻留 KV 容量上差异巨大，同一 batch 下的 TPOT 不可直接横比。</p>\n<div class=\"formula\">$$\\text{可比性}=\\mathbb{1}\\big[\\text{负载同分布}\\big]\\cdot\\mathbb{1}\\big[\\text{奖励同定义}\\big]\\cdot\\mathbb{1}\\big[\\text{硬件同档位}\\big]\\cdot\\mathbb{1}\\big[\\text{SLO 同约束}\\big]$$</div>\n<p>这个指示函数的意义在于：四项中任一为假，两个数字的差值就没有工程含义。论文材料在这四项上均未闭合，因此它的结果只能作为<strong>方向性证据</strong>，不能进入容量规划的输入表。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-44\">四十四 · 硬件档位与 batch/并发的耦合：为什么 batch 不能单独报</h3>\n<p>在 Blackwell 上讨论补全推理，batch 与并发必须与档位绑定报出。原因在于 KV 预算约束：<span class=\"formula\">$$|\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}}$$</span> 中的 $B_{\\mathrm{kv}}$ 是每卡或每域的可用容量，而它随档位变化。B200 单卡与 GB200 NVL72 机柜级域在可驻留 KV 总量上不在一个量级，同一 batch size 在两者上对应的“是否触发抢占/重算”状态完全不同。因此“batch=8 时 TPOT 为某值”这种表述若不附档位与上下文长度，等于没有信息。</p>\n<p>更细的耦合点是并发与连续批处理的交互。低延迟补全场景通常要求小批低时延，材料指出需与 KV 预算联动控制。当并发请求数上升，调度器为维持 TPOT 会把新请求插入正在解码的批次，此时若前缀缓存命中率下降，未命中部分重新预填会挤占解码步的算力，TPOT 出现长尾。工程上应把<strong>并发—命中率—TPOT 长尾</strong>三者作为一组联合指标报出，而不是单报平均 TPOT。具体例子：假设某档位下 16 并发、平均上下文 8K token，若前缀缓存命中率从高位跌到低位，预填 token 量翻倍，解码步被预填切分，P99 TPOT 相对 P50 的抬升会显著放大；这个放大倍数才是容量规划要用的数，而论文未提供此类数据。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>论文材料状态</th><th>复现时必须自建</th></tr></thead><tbody><tr><td>硬件档位</td><td>未给出</td><td>固定 B200 / B300 / GB200 NVL72 之一并注明域规模</td></tr><tr><td>batch 与并发</td><td>未给出</td><td>报 batch 时绑定上下文长度与命中率</td></tr><tr><td>SLO 数值</td><td>未给出</td><td>显式给出 TTFT/TPOT 上限及统计分位</td></tr><tr><td>量化方案</td><td>未给出</td><td>注明 NVFP4/FP8 及是否作用于 KV</td></tr></tbody></table>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-45\">四十五 · 指标定义：TTFT、TPOT、吞吐、显存、功耗各自的分母</h3>\n<p>补全请求的 TTFT 由两部分构成：命中前缀的复用开销与未命中部分的预填开销。写成可核算的形式，设请求上下文总长为 $L$，命中长度为 $L_h$，则</p>\n<div class=\"formula\">$$t_{\\mathrm{TTFT}}\\approx t_{\\mathrm{queue}}+t_{\\mathrm{prefill}}(L-L_h)+t_{\\mathrm{reuse}}(L_h)$$</div>\n<p>关键在于 $t_{\\mathrm{reuse}}(L_h)$ 并非零：前缀缓存以文件路径与版本为键，键匹配后仍需搬运 KV 到计算位置，这部分是带宽代价。因此“命中率高所以 TTFT 低”不是自动成立的，要看命中 KV 的搬运是否落在关键路径上。工程口径应把 TTFT 拆成预填项与复用项分别报，否则无法判断优化该投向缓存键设计还是预填算力。</p>\n<p>TPOT 的分母是解码步数，但补全场景的解码步数很短（补全片段通常不长），于是固定开销占比被放大：每步的调度开销、草稿验证开销在短解码中摊不薄。这就是为什么投机解码在补全上未必划算——材料指出草稿模型与仓库上下文的一致性未经验证，若草稿接受率低，验证开销反而拉高 TPOT。吞吐指标同理：补全的 tokens/s 若按请求数计与按 token 数计会给出相反结论，因为短补全请求的调度开销占比高。显存口径必须区分权重、KV、激活与缓存元数据，其中 KV 是随并发线性增长的主项；功耗口径在 NVL72 机柜级才有意义，单卡功耗数字对容量规划帮助有限。</p>\n<p>具体例子：一个 2K token 的补全请求，若命中 1.5K、未命中 0.5K，预填项只占小头，TTFT 由复用搬运与排队主导；反之若版本错配导致全量重预填，TTFT 由 2K 预填主导，量级差异明显。这就是版本键设计直接决定 TTFT 口径的原因。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-46\">四十六 · 奖励口径与离线指标的错位</h3>\n<p>本文的奖励是序列级的：<span class=\"formula\">$$\\max_{\\pi}\\ \\mathbb{E}_{x\\sim\\mathcal{D},\\ y\\sim\\pi(\\cdot\\mid x)}\\left[\\,r(x,y)\\,\\right]$$</span> 其中 $r$ 与补全是否被采纳或通过校验挂钩。这个定义与离线 pass@k 的错位在于：采纳信号稀疏且带延迟，且受用户行为噪声影响；离线指标则在固定测试集上稠密可算。二者不可换算，也不能用离线指标的提升去推断在线采纳率的提升。</p>\n<p>工程含义是：评估这类方法必须建立<strong>在线 A/B 口径</strong>——同一编辑流分布下，对照组与实验组的采纳率、校验通过率、以及每次请求的 KV 占用与 TPOT 分位。材料明确指出奖励稀疏且依赖用户采纳，策略学习在真实编辑流中可能受噪声与延迟反馈影响而不稳定，因此单次实验的采纳率差值需要按请求量做置信区间，而不是报点估计。另一个口径陷阱是把强化学习奖励等同于离线指标：若论文只报离线通过率，读者会误以为在线采纳同向变化，而材料未提供任何在线数据支撑这一推断。</p>\n<p>具体机制上，奖励回传路径与推理路径是解耦的：推理侧只关心上下文组织层选出的片段集合与顺序，奖励则更新选择策略。评估时应把“策略更新后的上下文选择分布”与“前缀缓存命中率”作为中间指标报出，因为前者直接改变后者，而后者直接改变 TTFT。这条因果链若不在口径中体现，就无法解释任何观测到的延迟变化。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-47\">四十七 · 哪些提升不可比：四类典型误读</h3>\n<ul>\n<li><strong>跨档位横比</strong>：B200 单卡与 GB200 NVL72 域内的 TPOT 不可比，因为可驻留 KV 容量与 NVLink 域规模不同，同一并发下的抢占行为不同。材料未给档位，任何跨论文的延迟对比都缺一项。</li>\n<li><strong>跨负载横比</strong>：短上下文单文件补全与多文件长上下文补全的 TTFT 不可比，前者预填项小、后者预填项主导。材料未给请求长度分布，因此无法判断两篇论文是否同分布。</li>\n<li><strong>跨奖励定义横比</strong>：在线采纳率与离线 pass@k 不可相减。本文奖励为在线信号，若另一篇报离线指标，二者差值无意义。</li>\n<li><strong>跨量化方案横比</strong>：NVFP4/FP8 作用于权重与作用于 KV 对显存与 TPOT 的影响不同，材料未给量化方案，因此无法判断某延迟数字是否含量化收益。</li>\n</ul>\n<p>这四类误读的共同根源是把<strong>机制收益</strong>当成<strong>可加的性能收益</strong>。本文的机制收益是：上下文组织层在 KV 预算内截断，截断策略影响命中率与补全质量；前缀缓存按路径与版本复用；奖励把选择与生成联合优化。这些机制在 Blackwell 上的实际收益取决于档位、量化与 SLO 数值，而这三项材料均未闭合。因此正确的引用方式是“该机制在原理上降低预填开销”，而不是“该机制带来若干毫秒的 TTFT 下降”。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-48\">四十八 · 复现口径的最小清单</h3>\n<p>若要在 Blackwell 上评估这类方法，最小口径清单应包含：固定档位与域规模（B200/B300/GB200 NVL72 之一）；固定量化方案并注明是否作用于 KV；固定上下文长度分布与并发梯度；TTFT 与 TPOT 按 P50/P99 分位报，并拆出预填项与复用项；显存按权重/KV/激活分项报；吞吐同时按请求数与 token 数报；在线采纳率按请求量给置信区间。前缀缓存命中率与版本错配率必须作为一等指标，因为材料指出未区分文件版本会导致缓存错配，复用错误 KV 会污染补全结果——这是正确性问题，不是性能问题，任何口径都必须先排除它。</p>\n<p>最后落在工程判断上：这篇论文的可检验价值不在数字，而在它把<strong>上下文预算、缓存键版本、解码时延</strong>三者写进同一个约束式。复现时应以该约束式为口径骨架，把 $B_{\\mathrm{kv}}$ 与 $t_{\\mathrm{SLO}}$ 替换为你的档位与 SLO 实测值，再逐项填入命中率与分位延迟；填不满的格子就是材料未闭合的部分，也是你不能对外引用数字的部分。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-49\">四十九 · 口径拆解：奖励信号与 KV 预算的耦合边界</h3>\n<p>这套方案在推理侧真正的耦合点不在解码器，而在上下文组织层与 KV 预算的交互。RL 策略输出的不是 token，而是“哪些跨文件片段进入提示、以什么顺序、截断到何处”，这直接决定前缀缓存键的构成。设一次请求的候选片段集合为 <span class=\"inline-math\">S</span>，策略选出的子集为 <span class=\"inline-math\">A⊆S</span>，则 KV 占用可写成 <span class=\"inline-math\">|KV(A)| = Σ_{f∈A} L_f · h · d</span>（<span class=\"inline-math\">L_f</span> 为文件片段 token 数，<span class=\"inline-math\">h</span> 为层数，<span class=\"inline-math\">d</span> 为 KV 头维），而命中收益取决于 <span class=\"inline-math\">A</span> 与已缓存版本的交集。策略若倾向“多选”，KV 预算被挤爆；若倾向“少选”，缓存命中率下降、预填开销上升。RL 的序列级奖励只告诉策略“补全是否被采纳”，并不告诉它“这次选择让缓存命中率掉了多少”——这是口径上的第一个缺口。</p>\n<p>失效条件集中在三处。其一，奖励稀疏且带延迟：采纳信号来自编辑器回传，与请求之间隔着用户思考时间，策略更新时上下文版本可能已漂移，导致学到的选择偏好对应的是旧仓库快照。其二，版本错配：前缀缓存以文件路径与版本为键，若策略在同一会话中切换了依赖文件但未刷新版本标识，命中错误 KV 会污染补全，且这种污染不会体现在奖励里——用户只是不采纳，策略误以为是“上下文选错了”。其三，SLO 挤压：低延迟补全要求 <span class=\"inline-math\">t_decode ≤ t_SLO</span>，长上下文预填必须被缓存命中摊薄；当命中率低于阈值时，预填时间线性吃掉解码预算，此时策略再优化选择也无法挽回，属于系统层失效而非策略层失效。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>论文给定</th><th>部署侧需自行钉死</th></tr></thead><tbody><tr><td>硬件档位</td><td>未给出</td><td>B200/B300 单机或 GB200 NVL72 机柜，决定 KV 容量与 NVLink 域</td></tr><tr><td>量化</td><td>未给出</td><td>NVFP4/FP8 对 KV 与权重显存的影响需与补全质量联测</td></tr><tr><td>batch/并发</td><td>未给出</td><td>小批低时延 vs 连续批处理吞吐，二者不可直接换算</td></tr><tr><td>指标</td><td>仅定性</td><td>TTFT、TPOT、吞吐、显存、功耗需分档报告，跨档不可比</td></tr></tbody></table>\n<p>数字怎么读：论文未给出通过率、采纳率、延迟或吞吐的具体数值，因此任何“RL 带来 X% 提升”的说法都不可核验。可比的前提是同一硬件档位、同一量化方案、同一 batch 与并发配置、同一 SLO 约束下测同一指标；换档位（如从单机 B200 到 NVL72 机柜）后 TTFT 与吞吐的绝对值不可横向比较，只能看命中率与 KV 占用这类归一化量。工程判断落在具体机制上：把前缀缓存命中率与 KV 预算占用作为一等监控指标，与补全采纳率并列上报，才能在 RL 策略收益被预填开销抵消时及时识别，而不是把系统失效误读为策略失效。</p>\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-50\">五十 · 迁移到非代码领域：奖励语义先塌，再谈上下文</h3>\n<p>这套方案的可迁移性不取决于强化学习算法本身，而取决于两件事能否在目标领域成立：一是存在一个可观测、可回传、与任务质量相关的采纳或校验信号；二是上下文组织层能在 KV 预算内挑出高价值证据。代码补全之所以适配，是因为采纳信号天然存在——用户按下 Tab 或拒绝，校验信号也天然存在——编译、测试、静态检查。换到通用文本写作、客服回复、法律文书草拟，采纳信号退化为点赞、编辑距离或人工抽检，反馈延迟从秒级拉到小时乃至天级，奖励稀疏性急剧恶化。此时序列级策略优化退化为高方差估计，上下文选择层学到的排序偏好会被噪声主导。</p>\n<p>迁移时要改的第一处是奖励构造。代码场景的奖励可写成采纳指示与校验通过的合取，迁移到弱校验领域必须引入代理奖励，例如以编辑后保留率作为奖励的连续化版本：</p>\n<div class=\"formula\">$$r(x,y)=\\alpha\\cdot\\mathbb{1}[\\text{accepted}]+\\beta\\cdot\\frac{|\\mathrm{tokens\\ kept}(y,y')|}{|y|}-\\gamma\\cdot\\frac{|\\mathrm{KV}(x)|}{B_{\\mathrm{kv}}}$$</div>\n<p>第三项显式惩罚上下文预算占用，否则策略会倾向于把所有可检索片段塞进提示以抬高采纳率，直接冲垮前缀缓存与解码时延。第二处要改的是上下文组织层的键设计：代码场景用文件路径加版本做前缀缓存键，天然离散、可比对；迁移到文档流或工单流，版本语义模糊，需要引入内容哈希或编辑序号作为键，否则版本错配会静默复用错误 KV。系统代价上，弱校验领域的奖励回传周期拉长，意味着策略更新频率下降，前缀缓存命中率的提升无法通过在线学习快速兑现，工程上更现实的路径是先做静态上下文排序，再逐步引入策略梯度。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-51\">五十一 · 迁移到其他代码模型：改的是缓存键与草稿一致性，不是策略头</h3>\n<p>把同一套上下文选择与生成策略套到另一个代码模型上，最容易被低估的成本是前缀缓存的可复用性。前缀缓存按文件路径与版本复用 KV，其收益依赖分词器与位置编码的一致性：换模型意味着 tokenizer 边界变化，同一文件片段编码出的 token 序列长度不同，缓存键必须带上模型标识与分词器版本，否则跨模型复用会直接污染结果。工程判断是：缓存键至少应为（模型标识，分词器版本，文件路径，内容哈希）四元组，缺一不可。</p>\n<p>第二个改动点是投机解码的草稿模型。低延迟补全下草稿模型先出候选再验证，草稿模型与目标模型共享同一份仓库上下文才有一致性；若草稿模型是通用小模型、未见过该仓库的跨文件证据，接受率会显著下降，验证开销反噬时延。迁移到新模型时，草稿模型要么从目标模型蒸馏，要么至少用同一上下文组织层喂入相同片段。系统代价体现在解码时延的方差上：草稿不一致时，验证失败的 token 需要回退重算，尾延迟抬升，而补全请求恰恰对尾延迟最敏感。规模上限也在这里显形——草稿模型越大，接受率越高但单步开销越大；草稿模型越小，接受率下降。存在一个由目标模型规模与上下文长度共同决定的拐点，超过该拐点投机解码不再净收益，此时应退回纯自回归并依赖前缀缓存摊薄预填。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-52\">五十二 · 规模上限：KV 预算与 SLO 的联合约束决定天花板</h3>\n<p>这套方案的规模上限不是模型参数量，而是「在给定 KV 预算与解码时延约束下，能稳定复用的跨文件上下文规模」。形式化地，设单请求可用 KV 预算为 B_kv，前缀缓存命中率为 h，未命中部分的预填时间为 t_prefill，解码步时间为 t_step，则单请求时延近似为：</p>\n<div class=\"formula\">$$t\\approx(1-h)\\cdot t_{\\mathrm{prefill}}(|x|)+N_{\\mathrm{out}}\\cdot t_{\\mathrm{step}}$$</div>\n<p>当仓库规模增长，候选跨文件片段增多，上下文组织层被迫在更大候选集上排序，命中率 h 未必同步上升——因为版本更新频繁的文件会持续触发缓存失效。真实编辑流中，活跃文件的版本变更率决定了 h 的上限；变更率越高，缓存越难摊薄预填，长上下文复用收益被预填开销抵消。这就是论文所指出的低延迟 SLO 下长上下文复用收益可能被抵消的机制根源。工程判断：当活跃文件变更率使 (1-h)·t_prefill 逼近 t_SLO 的显著比例时，继续扩大上下文窗口不再划算，应转而缩短上下文、提高单片段信息密度，或把跨文件证据压缩为结构化摘要再入提示。Blackwell 侧的 NVFP4/FP8 量化能压低 KV 显存占用、抬高 B_kv，从而抬高 h 的有效上限，但量化对补全质量的损伤需在目标仓库上验证，不能默认无损。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-53\">五十三 · 哪里不适用：三类场景应当直接放弃这套策略层</h3>\n<p>第一类是高变更率、低复用率的仓库。若编辑流以新建文件、大范围重构为主，文件版本几乎不重复，前缀缓存命中率结构性偏低，上下文组织层学到的排序偏好没有稳定的复用对象可依附，策略收益被预填开销吞掉。第二类是强确定性校验场景。当补全结果必须通过严格类型检查或形式化验证，采纳信号与校验信号高度一致且几乎二值化，监督微调加规则过滤已能覆盖大部分收益，引入序列级强化学习带来的策略不稳定性（奖励稀疏、延迟反馈）超过其边际收益。第三类是单文件、短上下文的补全请求。此时跨文件证据稀疏，上下文组织层无候选可排，KV 预算不构成约束，方案退化为普通解码器，强化学习信号只作用于生成策略，与仅优化下一 token 的基线差距被压缩。</p>\n<p>判断标准可以写成一个粗略的准入条件：只有当跨文件候选集非空、活跃文件版本变更率低到使缓存命中可摊薄预填、且存在可回传的采纳或校验信号时，这套策略层才值得部署。三者缺一，应退回静态检索加监督微调的组合。这不是口号，而是由上面的时延公式与缓存键机制直接推出的工程边界。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-54\">五十四 · 迁移检查清单：把改动落到可核验的接口上</h3>\n<p>迁移到新模型或新领域时，按以下顺序核验，每项都对应一个具体机制与一个系统代价：</p>\n<ul>\n<li>缓存键四元组是否落地（模型标识、分词器版本、路径、内容哈希）。缺失任一项，版本错配会静默污染补全，代价是错误 KV 复用导致的补全质量下降，且难以从时延指标上察觉。</li>\n<li>上下文组织层的截断是否显式受 B_kv 约束，并在截断处记录丢弃片段。代价是截断策略直接影响命中率与补全质量，无记录则无法归因。</li>\n<li>奖励回传链路是否区分采纳与校验，是否带时间戳以估计反馈延迟。代价是延迟反馈使策略更新滞后，需监控策略版本与线上行为的偏差。</li>\n<li>投机解码的草稿模型是否与目标模型共享同一上下文组织层输出。代价是草稿不一致抬高尾延迟，补全场景对尾延迟最敏感。</li>\n<li>监控是否覆盖前缀缓存命中率、KV 占用、解码时延分位数与补全采纳率四项。代价是任一指标缺失都会让失败模式（缓存错配、预填超时、奖励稀疏）无法定位。</li>\n</ul>\n<p>最后一项工程判断落在量化与档位的匹配上：论文未给出硬件档位与并行拓扑，Blackwell 部署需自行确定 B200/B300/GB200 NVL72 档位。判断依据应是 KV 预算与 SLO 的联合约束——若单机 KV 容量不足以让活跃仓库上下文的命中部分常驻，则 NVL72 的跨节点显存聚合才有意义；若上下文规模本就被截断策略压得很小，单机档位加 NVFP4/FP8 量化即可满足，跨节点通信开销反而成为负担。迁移的边界最终由这条容量与带宽的算术决定，而非由策略层的复杂度决定。</p>\n\n<h3 id=\"paper-enhancing-repository-level-code-comp-2026-sec-55\">五十五 · 迁移边界：策略层可移植，奖励与缓存契约不可移植</h3>\n<p>把该方案搬到别的模型或领域，能带走的只有“上下文选择—生成”的联合决策结构，不能带走的是奖励语义与缓存键契约。奖励来自补全被采纳或通过校验，这一信号在代码补全里天然与文件路径、版本、光标位置绑定；迁到文档续写、SQL 生成或配置修复时，采纳信号要么消失（无编译/测试校验），要么变成人工评分，稀疏度与延迟反馈都会恶化。此时策略会退化为对噪声的过拟合：强化学习目标仍是 <span class=\"formula\">$$\\max_{\\pi}\\mathbb{E}\\left[r(x,y)\\right]\\ \\text{s.t.}\\ |\\mathrm{KV}(x)|\\le B_{\\mathrm{kv}},\\ t_{\\mathrm{decode}}\\le t_{\\mathrm{SLO}}$$</span>，但 <span class=\"formula\">$$r$$</span> 的方差上升、<span class=\"formula\">$$B_{\\mathrm{kv}}$$</span> 与 <span class=\"formula\">$$t_{\\mathrm{SLO}}$$</span> 的可行域收窄，约束从“可优化”变成“不可辨识”。工程判断：只有当领域存在低成本、低延迟的自动校验（编译、类型检查、单测、schema 校验）时，这套奖励才值得迁移；否则应退回监督微调或静态检索，把强化学习留给上下文排序这类低维决策。</p>\n<p>缓存侧的可移植性更差。前缀缓存以文件路径与版本为键，这一契约假设“同一路径同一版本的内容确定且可复用”。迁到多租户仓库、分支并行编辑或跨语言 monorepo 时，版本标识的粒度决定命中率：按 commit 做键则编辑流中每次保存都失效，按文件内容哈希做键则跨分支复用可行但需额外哈希开销。版本错配的代价不是命中率下降，而是复用错误 KV 直接污染补全结果，且这种污染在低延迟 SLO 下难以被下游校验及时拦截。表里给出三类迁移场景的失效点与代价：</p>\n<table class=\"mini\"><thead><tr><th>迁移场景</th><th>主要失效机制</th><th>系统代价</th></tr></thead><tbody><tr><td>跨语言仓库</td><td>依赖图跨语言断裂，候选片段排序失真</td><td>上下文组织层误选，KV 预算被低价值片段占用</td></tr><tr><td>分支并行编辑</td><td>版本键粒度不足，缓存错配</td><td>重新预填比例上升，解码时延逼近 SLO 上限</td></tr><tr><td>无自动校验领域</td><td>奖励稀疏且延迟反馈</td><td>策略更新不稳定，采纳率信号无法归因</td></tr></tbody></table>\n<p>规模上限由两个量共同决定：前缀缓存命中率 <span class=\"formula\">$$h$$</span> 与单次未命中预填开销 <span class=\"formula\">$$t_{\\mathrm{pre}}$$</span>。有效解码时延近似 <span class=\"formula\">$$t_{\\mathrm{decode}}\\approx(1-h)\\,t_{\\mathrm{pre}}+t_{\\mathrm{gen}}$$</span>，当 <span class=\"formula\">$$h$$</span> 随仓库规模增大而下降（文件数增长快于编辑局部性），预填开销会吞掉缓存收益。Blackwell 上可用 NVFP4/FP8 压缩 KV 与权重来抬高 <span class=\"formula\">$$B_{\\mathrm{kv}}$$</span> 的等效容量，但量化误差会改变草稿模型与目标模型的一致性，投机解码的验证通过率随之波动——材料未给出该一致性验证，部署前必须自行测量。判断：该方案适用于“编辑局部性强、自动校验可得、版本键可精确构造”的仓库；一旦三者缺一，强化学习带来的策略收益会被预填时延与缓存错配抵消，此时应优先修缓存契约而非调策略。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Enhancing Repository-Level</text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> Code Complet…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Enhancing Repository-Le… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>真实仓库编辑流场景（论文未给出具体数据集名称与规模）</td></tr><tr><td>基线</td><td>监督微调补全基线（论文未给出具体基线名称）</td></tr><tr><td>主要结果</td><td>论文未给出可核验的数字结果；材料仅表明在真实仓库场景下用强化学习增强仓库级…</td></tr><tr><td>消融</td><td>论文未给出消融实验细节；材料未提供上下文选择、奖励形式或缓存策略的对照数据…</td></tr><tr><td>局限</td><td>论文未给出实验限制说明；从推理机制看，真实仓库编辑流的奖励稀疏、跨文件上下…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-enhancing-repository-level-code-comp-2026 · 共 9 个片段</p>\n";break;}}})();
